// Reel content. Each topic becomes one reel: auto cover slide + up to 8 content slides + auto recap slide (<= 10).
// Slide fields: h = heading, t = text (supports **bold** and `code`), a = animation name, p = animation params,
// ex = a concrete example box.  pre = prerequisite topic ids (must be "watched" before the reel is served).
'use strict';

window.RLTopics = [
// ───────────── Foundations ─────────────
// part 1
// ───────────── Foundations ─────────────
{ id: 'loop', title: 'The RL Loop', emoji: '🔁', track: 'Foundations', pre: [],
  hook: 'Learning by doing: try something, see what happens, adjust.',
  slides: [
    { h: 'Words you’ll need', g: [['Agent', 'the learner. It makes the choices.'], ['Environment', 'everything outside the agent: the world it acts in.'], ['Action', 'one choice the agent makes, like “move left”.'], ['Reward', 'a number the world hands back. High means good, low means bad.']] },
    { h: 'Two players', t: 'Reinforcement learning has two sides. The **agent** is the learner. The **environment** is the world around it. They take turns, again and again.', a: 'loop' },
    { h: 'One turn of the loop', a: "p1_turn", t: 'The agent looks at the situation, called the **state**. It picks an **action**. The world reacts: it moves to a **new state** and hands back a **reward**.' },
    { h: 'Think of a puppy', a: "p1_puppy", try: "Tap to give a treat whenever the puppy does a trick you like.", t: 'You say “sit”. The puppy tries something. If it sits, it gets a treat. Over many tries, it learns which action earns the treat.', ex: 'Puppy = agent. You and the room = environment. Treat = reward.' },
    { h: 'No answer key', t: 'Nobody tells the agent the right move. It only gets a score. That is the big difference from normal machine learning, where every example comes with the correct answer.' },
    { h: 'Rewards can be late', t: 'Often the score only arrives at the very end. The agent must work out which earlier choices deserved the credit.', ex: 'A chess bot learns it lost only after 60 moves. Which move was the mistake?' },
    { h: 'More examples', t: '🎮 A game AI presses buttons and gets points. 🦾 A robot moves its motors and gets closer to the cup. 📱 An app picks a video and you keep watching.' },
    { h: 'The goal', t: 'Collect as much reward as possible **over the long run**, not just on the next turn. Everything else in RL builds on this loop.' },
  ],
  recap: ['Agent acts, environment answers with a new state and a reward', 'No correct answers given, only scores', 'Goal: the most total reward over time'] },

{ id: 'returns', title: 'Rewards & Returns', emoji: '💰', track: 'Foundations', pre: ['loop'],
  hook: 'Why the agent cares about the total, not just the next snack.',
  slides: [
    { h: 'Words you’ll need', g: [['Reward', 'the score for one single step.'], ['Return', 'all the rewards from now on, added up.'], ['Episode', 'one full attempt, from start to finish, like one game.']] },
    { h: 'Reward: instant feedback', t: 'After every step the agent gets one number. Positive is good, negative is bad, zero means nothing special happened.' },
    { h: 'Return: the running total', t: 'The **return**, written G, adds up every reward from now until the end. The bars show rewards piling up into one total.', a: 'returns' },
    { h: 'Small now, big later', a: "p1_twoPaths", t: 'A step that costs a little now can lead to a big win later. So the agent should judge a choice by the **return**, not by the next reward.', ex: 'Studying tonight costs fun (minus 1). Passing the exam next week is worth plus 10.' },
    { h: 'A maze example', a: "p1_mazeReturn", ctl: [{"k": "cost", "l": "step cost", "min": -2, "max": 0, "step": 0.1, "v": -1}], try: "Drag the step cost to 0 and both routes tie.", t: 'Each step in a maze costs minus 1, and reaching the exit gives plus 10. The shortest path has the highest return, because it wastes the fewest steps.' },
    { h: 'Tasks that end', t: 'Some tasks have a natural finish: a game, a maze, a race. These are called **episodic**. Each attempt is one **episode**.' },
    { h: 'Tasks that never end', t: 'Others just keep going, like a thermostat or a stock trader. These are **continuing** tasks. Their return could grow forever, which the next reel fixes.' },
    { h: 'The big bet', t: 'RL assumes any goal can be written as “get the largest total reward”. Not everyone agrees, but it has worked surprisingly well.' },
  ],
  recap: ['Reward: the number for one step', 'Return: the sum of rewards from now on', 'Judge choices by their long-run return'] },

{ id: 'discount', title: 'The Discount Factor γ', emoji: '⏳', track: 'Foundations', pre: ['returns'],
  hook: 'A reward tomorrow is worth a bit less than a reward today.',
  slides: [
    { h: 'Words you’ll need', g: [['Return', 'all the rewards from now on, added up.'], ['Discount factor γ', 'gamma, a number between 0 and 1 that shrinks future rewards.'], ['Horizon', 'how far into the future the agent effectively cares.']] },
    { h: 'Money today vs later', t: 'Would you take 100 rupees now or 100 rupees in a year? Most people pick now. RL agents are built to feel the same way.' },
    { h: 'Shrink the future', t: 'Each step into the future, a reward is multiplied by **γ** once more. One step away: times γ. Two steps: times γ twice. The bars shrink as they get further.', a: 'discount' },
    { h: 'A worked example', a: "p1_gammaBars", ctl: [{"k": "gamma", "l": "γ", "min": 0, "max": 1, "step": 0.01, "v": 0.9}], try: "Drag γ and watch far-away rewards shrink or grow.", t: 'Say γ is 0.9 and a reward of 10 is three steps away. It counts as 10 times 0.9 times 0.9 times 0.9, which is about 7.3.' },
    { h: 'Why bother?', t: 'Three reasons. It keeps never-ending sums from blowing up. It makes the agent prefer faster wins. And the far future is uncertain anyway.' },
    { h: 'Small γ: impatient', a: "p1_gammaChoice", ctl: [{"k": "gamma", "l": "γ", "min": 0, "max": 1, "step": 0.01, "v": 0.5}], try: "Push γ above 0.68 and the robot switches to the big gift.", t: 'With γ close to 0, only the next reward or two matter. The agent grabs quick wins and ignores long plans.', ex: 'With γ = 0.5, a reward 10 steps away counts for about one thousandth.' },
    { h: 'γ close to 1: patient', t: 'With γ near 1, far-away rewards still count. The agent plans ahead, but learning is slower and noisier.' },
    { h: 'Rule of thumb', a: "p1_horizon", ctl: [{"k": "gamma", "l": "γ", "min": 0.5, "max": 0.995, "step": 0.005, "v": 0.9}], try: "Slide γ towards 0.99 and watch how far the agent looks.", t: 'The agent looks roughly **1 divided by (1 − γ)** steps ahead. With γ = 0.99, that is about 100 steps.' },
  ],
  recap: ['Each step away multiplies a reward by γ', 'Small γ = impatient, γ near 1 = patient', 'Looks about 1/(1−γ) steps ahead'] },

{ id: 'mdp', title: 'Markov Decision Process', emoji: '🗺️', track: 'Foundations', pre: ['loop'],
  hook: 'The board game that almost every RL problem is written as.',
  slides: [
    { h: 'Words you’ll need', g: [['State', 'a snapshot of the situation right now.'], ['Transition', 'the move from one state to the next after an action.'], ['Probability', 'how likely something is, from 0 (never) to 1 (always).']] },
    { h: 'A rulebook for the world', t: 'A **Markov Decision Process**, or MDP, is just a careful description of the world the agent lives in. Most RL problems are written this way.' },
    { h: 'The ingredients', t: 'A list of **states**. A list of **actions**. Rules for where each action can take you. A **reward** for each move. And the discount γ.' },
    { h: 'A tiny MDP', t: 'A race car can be Cool, Warm or Overheated. Driving fast earns plus 2 but might overheat it, which costs minus 10. Driving slow is safe but earns less.', a: 'mdp' },
    { h: 'Luck is allowed', a: "p1_slippery", try: "Tap to make the robot step right. Count how often it slips.", t: 'The same action can lead to different results. Driving fast while Warm might keep you Warm, or might overheat you. The chances are fixed, but the outcome is random.' },
    { h: 'The Markov property', a: "p1_markov", t: 'The current state tells you **everything you need** about the future. How you got here does not matter.', ex: 'Chess: the board is enough. You don’t need the move history to pick the next move.' },
    { h: 'When it fails', t: 'Sometimes the state hides things. One frozen frame of a ball game doesn’t show which way the ball is moving. Then the snapshot is not enough.' },
    { h: 'Why it matters', t: 'If the state is a full summary, the agent can decide using only “where am I now?”. That makes learning far simpler.' },
  ],
  recap: ['MDP = states, actions, transition rules, rewards, γ', 'Outcomes can be random', 'Markov: the present state is all you need'] },

{ id: 'policy', title: 'Policies', emoji: '🧭', track: 'Foundations', pre: ['mdp'],
  hook: 'The agent’s rulebook: in this situation, do that.',
  slides: [
    { h: 'Words you’ll need', g: [['Policy π', 'pi, the agent’s strategy: what to do in each state.'], ['Deterministic', 'always the same choice.'], ['Stochastic', 'involves chance, like rolling a die.']] },
    { h: 'What is a policy?', t: 'A **policy** is the agent’s behaviour written down: for every state, which action to take. The arrows show one policy for a small grid world.', a: 'gridPolicy' },
    { h: 'Like a cheat sheet', a: "p1_lookup", t: 'Imagine a card that says “if you see this, do that” for every situation. Following the card is following the policy.', ex: 'Red light: stop. Green light: go. Yellow: slow down.' },
    { h: 'Deterministic policies', t: 'A **deterministic** policy always picks the same action in the same state. It is simple to write down and easy to predict, which is great for a robot arm on a factory line.' },
    { h: 'Stochastic policies', a: "p1_stoch", ctl: [{"k": "rand", "l": "randomness", "min": 0, "max": 1, "step": 0.05, "v": 0.3}], try: "Slide randomness to 0 for a deterministic policy, up for chaos.", t: 'Give each action a chance instead. For example: go left 70 percent of the time, right 30 percent. Handy for trying new things.', ex: 'In rock-paper-scissors, the best policy is one third each. Being predictable loses.' },
    { h: 'Learning = better policies', t: 'Almost every RL method is a recipe for taking the current policy and turning it into a better one, step by step.' },
    { h: 'The best policy', t: 'The **optimal policy**, written π star, earns at least as much return as any other policy, from every state.' },
  ],
  recap: ['Policy π: what to do in each state', 'Deterministic (fixed) or stochastic (chances)', 'RL searches for the best policy π*'] },

{ id: 'values', title: 'Value Functions', emoji: '📈', track: 'Foundations', pre: ['policy', 'discount'],
  hook: 'How good is it to be here? How good is this move?',
  slides: [
    { h: 'Words you’ll need', g: [['Value', 'how much return you expect from here, on average.'], ['Expected', 'the average result if you could try many times.'], ['V and Q', 'V scores a state. Q scores a state plus an action.']] },
    { h: 'A score for every place', t: 'A **value function** gives each state a score: how much total reward you can expect from there. Bright squares are worth more.', a: 'gridPolicy', p: { heat: true } },
    { h: 'State value V(s)', a: "p1_valueTap", try: "Tap any square to see its value and the walk behind it.", t: 'V of s answers one question: “If I start in this state and keep following my policy, how much return do I collect on average?” One number per state.' },
    { h: 'Action value Q(s, a)', a: "p1_qcell", t: 'Q of s, a answers: “If I take **this action** here first, and follow my policy afterwards, how much return do I get?”', ex: 'Standing at a fork in the road: Q tells you how good “left” is and how good “right” is.' },
    { h: 'Why Q is handy', t: 'If you know Q, acting well is easy. In each state, **pick the action with the biggest Q**. No map of the world needed.' },
    { h: 'Chess intuition', t: 'Strong chess players have a feel for value. They don’t calculate every future move. They glance at a position and sense whether it is good or bad.', ex: '“This position is winning for white” is a high V. “Taking the queen here is great” is a high Q.' },
    { h: 'Values depend on the player', t: 'The same chess position is worth more to a grandmaster than to a beginner. So values are always measured **for a particular policy**.' },
  ],
  recap: ['V(s): expected return from a state', 'Q(s, a): expected return of an action in a state', 'Pick the action with the biggest Q'] },

{ id: 'bellman', title: 'The Bellman Equation', emoji: '🪜', track: 'Foundations', pre: ['values'],
  hook: 'Value of here = reward now + discounted value of next.',
  slides: [
    { h: 'Words you’ll need', g: [['Value', 'how much total reward you expect from a state, on average.'], ['Recursive', 'defined in terms of itself, one step at a time.'], ['Backup', 'passing value from a future state back to the current one.'], ['Next state', 'where you land after one action.']] },
    { h: 'One step is enough', t: 'You don’t need to imagine the whole future. The value of here equals the reward for one step, plus the value of wherever you land.', a: 'backup' },
    { h: 'In words', t: '**Value of here = reward now + γ times value of next.** If the next state is random, average over where you might land.' },
    { h: 'A small worked example', a: "p1_backupStep", try: "Tap to run one sweep and watch the value travel left.", t: 'One step from the goal, the reward is 1, so that square is worth 1. With γ = 0.9, the square before it is worth 0.9, the one before that 0.81, and so on.' },
    { h: 'Like a rumour spreading', a: "valueIter", cap: "A gridworld solved by repeated sweeps. Colours are values: bright squares are worth a lot. Watch the brightness spread outwards from the flag, one step per sweep.", t: 'Value starts at the treasure and spreads outward, square by square, getting a little weaker each step.', ex: 'Ask a friend how far the beach is. They ask their neighbour, who has been there. The answer flows back.' },
    { h: 'For the best policy', t: 'To find the best value, use the **best** next action each time: take the max over actions instead of following a fixed policy.' },
    { h: 'Everywhere in RL', t: 'Value iteration, TD learning, Q-learning and DQN are all different ways of making this one equation come true.' },
  ],
  recap: ['Value = reward now + γ × value of next state', 'Value flows backwards from the future', 'The base of most RL algorithms'] },

// ───────────── Bandits & exploration ─────────────
{ id: 'explore', title: 'Exploration vs Exploitation', emoji: '🧪', track: 'Bandits', pre: [],
  hook: 'Order your favourite dish, or try something new?',
  slides: [
    { h: 'Words you’ll need', g: [['Exploit', 'use what you already know works.'], ['Explore', 'try something else to learn more.'], ['Greedy', 'always picking what looks best right now.']] },
    { h: 'The dilemma', t: 'Every choice is a trade-off. **Exploit** your current best option, or **explore** something new that might turn out even better.' },
    { h: 'Your favourite restaurant', a: "p1_restaurant", t: 'Always ordering your usual dish is exploiting. Trying the new place down the road is exploring. It might be awful, or it might become your new favourite.' },
    { h: 'Greedy gets stuck', t: 'A purely greedy agent picks whatever looks best so far. One lucky early win and it may stick with a mediocre option forever.', a: 'bandit', p: { mode: 'greedy' } },
    { h: 'Too much exploring', t: 'The opposite mistake: always trying new things means you rarely enjoy the good ones you found. Endless experimenting wastes reward.' },
    { h: 'The balance', a: "p1_epsLive", ctl: [{"k": "eps", "l": "ε explore", "min": 0, "max": 0.5, "step": 0.05, "v": 0.1}], try: "Try ε = 0, 0.1 and 0.5. Which ends highest?", t: 'Explore a lot at first, when you know very little. Then explore **less as you become more sure**, and spend more of your time on the options you know are good.', ex: 'New in town: try many cafés. After a year: mostly go to the best two.' },
    { h: 'Real life', t: '🎵 Music apps mix your favourites with new songs. 💊 Doctors give the best-known drug, but also test new ones in trials.' },
    { h: 'Strategies ahead', t: 'Random tries (ε-greedy), optimism (UCB), random guesses from beliefs (Thompson sampling), and curiosity. Each has its own reel.' },
  ],
  recap: ['Exploit the known best vs explore the unknown', 'Pure greedy can lock in a bad choice', 'Explore less as you grow more certain'] },

{ id: 'bandits', title: 'Multi-Armed Bandits', emoji: '🎰', track: 'Bandits', pre: ['explore'],
  hook: 'RL with one room and a row of slot machines.',
  slides: [
    { h: 'Words you’ll need', g: [['Arm', 'one option you can pick, like one slot machine.'], ['Payout', 'the reward an arm gives when pulled.'], ['Regret', 'how much you lost by not always picking the best arm.']] },
    { h: 'The setup', a: "p1_pullYourself", try: "Tap a machine to pull it. Can you find the best one?", t: 'A row of slot machines. Each one pays out differently on average, but you don’t know which is best. Every turn you pull one. Win as much as you can.' },
    { h: 'Why “bandit”?', t: 'Old slot machines had one lever, an “arm”, and took your money, like a bandit. Many machines means a **multi-armed bandit**.' },
    { h: 'Watch it learn', t: 'Each bar is one machine’s estimated payout. Pulling an arm updates its estimate. The question is always which arm to pull next.', a: 'bandit', p: { mode: 'eps' } },
    { h: 'Only one situation', t: 'Pulling an arm doesn’t change the world. There are no states to plan over. That makes bandits the purest test of exploring versus exploiting.' },
    { h: 'Regret', a: "p1_regret", t: 'Compare your winnings to someone who always pulled the best arm. The gap is your **regret**. Good methods keep regret growing slowly.' },
    { h: 'Real uses', t: 'Websites test two designs and send more visitors to the better one. Ad systems and news apps work the same way.', ex: 'Show headline A or headline B? Each click is a reward.' },
    { h: 'Adding context', t: '**Contextual bandits** also look at who the user is before choosing. They sit halfway between bandits and full RL.' },
  ],
  recap: ['Several arms, unknown payouts, pick one each turn', 'Measure performance by regret', 'Used in A/B tests, ads, recommendations'] },

{ id: 'epsgreedy', title: 'ε-Greedy', emoji: '🎲', track: 'Bandits', pre: ['bandits'],
  hook: 'Mostly do the best thing, occasionally roll the dice.',
  slides: [
    { h: 'Words you’ll need', g: [['ε (epsilon)', 'a small number, like 0.1, that sets how often you act randomly.'], ['Estimate', 'your current best guess of how good an option is.'], ['Decay', 'shrinking a number gradually over time.']] },
    { h: 'The rule', t: 'Most of the time, pick the option that looks best. But with a small chance **ε**, pick a completely random option instead.', a: 'bandit', p: { mode: 'eps' } },
    { h: 'In numbers', a: "p1_coin", ctl: [{"k": "eps", "l": "ε", "min": 0, "max": 1, "step": 0.05, "v": 0.1}], try: "Raise ε and the gold explore zone grows.", t: 'With ε = 0.1, you pick the best-looking option 9 times out of 10. One time in 10, you roll the dice and pick any option at random, even a bad-looking one.' },
    { h: 'Why it works', t: 'Because every option keeps getting tried now and then, a wrong first impression eventually gets corrected.', ex: 'A café you rated badly after one off day gets a second chance, and you discover it’s great.' },
    { h: 'Shrink ε over time', a: "p1_decay", t: 'Start with lots of random tries, then lower ε as your estimates firm up. Learn first, then cash in.', ex: 'The Atari-playing DQN started fully random and slowly dropped to 10 percent random.' },
    { h: 'The weakness', t: 'It explores **blindly**. It wastes pulls on options already known to be terrible, just as often as on promising ones.' },
    { h: 'Still a favourite', t: 'It takes one line of code and works surprisingly well, so it is often the first thing people try.' },
  ],
  recap: ['Random action with chance ε, otherwise the best-looking one', 'Simple and surprisingly strong', 'Explores blindly; usually shrink ε over time'] },

{ id: 'ucb', title: 'Upper Confidence Bound', emoji: '🌟', track: 'Bandits', pre: ['bandits'],
  hook: 'Be optimistic about what you haven’t tried much.',
  slides: [
    { h: 'Words you’ll need', g: [['Estimate', 'your current best guess of how good an option is.'], ['Uncertainty', 'how unsure you are about an estimate.'], ['Bonus', 'extra points added to make an option more tempting.'], ['Optimism', 'assuming the best about what you don’t know yet.']] },
    { h: 'Benefit of the doubt', t: 'If you’ve barely tried something, it **might** be great. UCB gives such options extra credit so they get checked.' },
    { h: 'The score', t: 'Each arm gets a score: **its estimate plus an uncertainty bonus**. Always pull the arm with the highest score. The tall caps on the bars are the bonuses.', a: 'bandit', p: { mode: 'ucb' } },
    { h: 'The bonus shrinks', a: "p1_ucbBonus", try: "Tap an arm to pull it and watch its gold bonus shrink.", t: 'Every time you pull an arm, you learn more about it, so its bonus gets smaller. Rarely-tried arms keep a big bonus until checked.' },
    { h: 'Smarter than random', a: "p1_regret", p: {"focus": "ucb"}, cap: "Total regret over time for three strategies. Gold is UCB: it explores only where it is unsure, so its regret flattens out sooner than random ε-greedy in teal or greedy in red.", t: 'Unlike ε-greedy, UCB stops trying arms it is confident are bad. It spends its exploring where it can still learn something.', ex: 'A new café gets a visit. After three bad coffees, you stop going.' },
    { h: 'A famous descendant', t: 'The same idea, used for choosing moves in a game tree, is called **UCT**. It helped AlphaGo decide which moves to think about.' },
    { h: 'Where it shines', t: 'UCB needs no random dice and no tuning of ε. It works best when payouts stay steady over time. If the best arm keeps changing, its old confidence can mislead it.', ex: 'Steady: which button colour gets more clicks. Changing: which news story is hot today.' },
  ],
  recap: ['Score = estimate + uncertainty bonus', 'The bonus shrinks the more you try an arm', 'Also guides game-tree search (UCT)'] },

{ id: 'thompson', title: 'Thompson Sampling', emoji: '🎯', track: 'Bandits', pre: ['bandits'],
  hook: 'Act on a random guess drawn from your beliefs.',
  slides: [
    { h: 'Words you’ll need', g: [['Belief', 'your sense of how likely each possible payout is.'], ['Distribution', 'a spread of possible values with their chances.'], ['Sample', 'one random draw from a distribution.']] },
    { h: 'Beliefs, not single numbers', t: 'Instead of one guess per arm, keep a **range** of what its payout could be. A wide range means unsure. A narrow range means confident.', a: 'bandit', p: { mode: 'ts' } },
    { h: 'The rule', a: "p1_tsSample", t: 'Each turn, draw one random guess from every arm’s range. Pull the arm whose guess came out highest. Then update that arm’s range.' },
    { h: 'Built-in balance', t: 'Unsure arms produce wild guesses, so now and then they win the draw: that is exploring. Clearly good arms win most draws: that is exploiting.' },
    { h: 'An example', t: 'An online shop has two product photos. Photo A: 50 clicks out of 1000 views. Photo B: 3 clicks out of 4 views.', ex: 'B looks amazing but is based on almost nothing. Its wide range means it still gets shown sometimes, until the shop knows.' },
    { h: 'Ranges get narrower', a: "p1_betaTap", try: "Tap 👍 or 👎 to add results and watch the hill narrow.", t: 'Every pull adds evidence, so ranges tighten. Over time the agent naturally stops exploring arms it has figured out.' },
    { h: 'Old but strong', t: 'The idea dates from 1933, and it is still one of the best methods for many bandit problems today.' },
  ],
  recap: ['Keep a belief range for each arm', 'Draw a guess from each, pull the highest', 'Exploration comes naturally from uncertainty'] },
// part 2
{ id: 'valueiter', title: 'Value Iteration', emoji: '🌊', track: 'Planning', pre: ['bellman'],
  hook: 'Know the rules? Spread value outward from the goal, step by step.',
  slides: [
    { h: 'Words you’ll need', g: [['State', 'where the agent is right now, like one square of a maze'], ['Value', 'how much total reward you can expect from a state onward'], ['Model', 'the rules of the world: where each move takes you and what it pays'], ['Greedy', 'always picking whatever looks best right now']] },
    { h: 'The problem', t: 'Sometimes you already **know the rules** of the world, like a maze on paper. Then you don’t need trial and error. You can sit down and **compute** the best plan.', ex: 'A delivery robot with a full floor map of the warehouse.' },
    { h: 'The core idea', a: "p2_viGoal", ctl: [{"k": "g", "l": "γ", "min": 0.5, "max": 0.99, "step": 0.01, "v": 0.9}], try: "Tap any square to move the goal. Drag γ to change how fast values fade.", t: 'Think of the goal as a lamp. Its light spreads to the squares next to it, then to their neighbours, and so on. Each square learns **how close it is to the light**.' },
    { h: 'One sweep', t: 'Visit every state. For each, look at every move and ask: reward now, plus the value of where I land. Keep the **best** of those as the new value.', a: 'valueIter' },
    { h: 'A tiny example', a: "p2_viLine", ctl: [{"k": "g", "l": "γ", "min": 0.5, "max": 0.99, "step": 0.01, "v": 0.9}], try: "Drag γ: at 0.9 you get 10, 9, 8.1 … as in the text.", t: 'The goal pays 10, and future reward is shrunk by 0.9 per step. After sweep 1, squares beside the goal are worth 10. After sweep 2, squares two steps away are worth 9.', ex: 'Three steps away: 0.9 × 9 = 8.1. The numbers fade with distance.' },
    { h: 'When to stop', t: 'Keep sweeping until the values **barely change**. Then the plan is easy: from any square, move to the neighbour with the highest value. That is the **greedy** policy.', a: 'gridPolicy', p: { heat: true } },
    { h: 'Where it’s used', t: 'Small planning problems with known rules: robot paths on small maps, stock and inventory decisions, simple games.', ex: 'How many units to reorder each week, given known demand odds.' },
    { h: 'The catch', t: 'It needs the full rules and a pass over **every** state. Fine for a grid of 100 squares, hopeless for Go, which has more board positions than atoms in the universe.' },
  ],
  recap: ['Needs the rules of the world', 'Sweep all states: best reward plus next value', 'Stop when values settle, then act greedily'] },

{ id: 'policyiter', title: 'Policy Iteration', emoji: '🔄', track: 'Planning', pre: ['bellman'],
  hook: 'Judge your plan, fix it, repeat, until nothing changes.',
  slides: [
    { h: 'Words you’ll need', g: [['Policy', 'the agent’s rulebook: in this situation, do that'], ['Value', 'how much total reward you can expect from a state onward'], ['Greedy', 'always picking whatever looks best right now']] },
    { h: 'The idea', t: 'Start with any plan, even a silly one. Then repeat two steps: **judge** how good the plan is, and **fix** it wherever a better move exists.' },
    { h: 'Step 1: evaluate', t: 'Work out the value of every state if you **follow the current policy**. This tells you how good each place is under your plan.', a: 'policyIter' },
    { h: 'Step 2: improve', a: "p2_piLoop", try: "Tap the picture to step through evaluate and improve yourself.", t: 'In each state, look one move ahead using those values. If some move looks better than what the policy does, **switch** to it.', ex: 'Your route to work goes via the highway. Values show the side road is faster from one junction, so you change that one turn.' },
    { h: 'It only gets better', a: "p2_piLoop", cap: "The same plan improving round by round. Values (numbers) only go up between rounds, and once no arrow flips, the plan is the best possible.", t: 'Each fix makes the plan **at least as good** as before. There are only so many possible plans, so it must stop, and when it stops, the plan is the best one.' },
    { h: 'Few rounds', t: 'It usually finishes in just a handful of rounds. The catch is that each evaluation step can be slow, because it scores every state.' },
    { h: 'The big template', t: 'Almost all RL is a loose version of this, called **generalised policy iteration**: estimate values a little, improve the policy a little, repeat.', ex: 'Actor-critic methods do exactly this, but with learning instead of exact sums.' },
  ],
  recap: ['Alternate: evaluate the plan, then improve it', 'Each round is at least as good as the last', 'Ends at the best plan', 'Template for most RL methods'] },

{ id: 'mc', title: 'Monte Carlo Learning', emoji: '🎬', track: 'Model-free', pre: ['values'],
  hook: 'Play to the end, then learn from what really happened.',
  slides: [
    { h: 'Words you’ll need', g: [['Episode', 'one full run of a task from start to finish, like one game'], ['Return', 'the total reward collected from a moment until the episode ends'], ['Value', 'the return you expect on average from a state'], ['Variance', 'how much results jump around from one try to the next']] },
    { h: 'The problem', t: 'Often we **don’t know the rules** of the world. We can’t compute values on paper. But we can play, and watch what happens.' },
    { h: 'The core idea', t: 'Like judging a restaurant by eating there many times. Play **whole episodes**, write down the return that followed each state, and **average** them.' },
    { h: 'How it works', t: 'After an episode ends, go back through every state you visited. Add the total reward that came after it to that state’s list, and update its average.', a: 'mc' },
    { h: 'A worked example', a: "p2_mcAvg", try: "Tap to play another game and watch the average move.", t: 'From one state, three games give returns of 10, 4 and 7. The value estimate is their average, 7. A fourth game scoring 9 nudges it to 7.5.', ex: 'Blackjack: value of holding 18 = average result over thousands of hands from 18.' },
    { h: 'Honest but noisy', a: "p2_mcAvg", ctl: [{"k": "luck", "l": "luck", "min": 0.5, "max": 5, "step": 0.5, "v": 3.5}], try: "Drag luck up: games vary more and the average takes longer to settle.", t: 'It uses real outcomes, so it never fools itself with guesses. But one very lucky or unlucky game swings the average a lot: **high variance**.' },
    { h: 'The catch', t: 'It can only learn when an episode **finishes**. For a task that never ends, like running a power grid, there is nothing to average.', ex: 'Next idea: learn after every step instead. That’s TD learning.' },
  ],
  recap: ['Learn from complete episodes', 'Value = average of the returns seen', 'Honest, but noisy', 'Must wait for the episode to end'] },

{ id: 'td', title: 'Temporal-Difference Learning', emoji: '⚡', track: 'Model-free', pre: ['values', 'bellman'],
  hook: 'Learn a guess from a slightly better guess, every single step.',
  slides: [
    { h: 'Words you’ll need', g: [['Value', 'how much total reward you expect from a state onward'], ['Estimate', 'your current best guess, which gets corrected over time'], ['Bootstrapping', 'improving a guess using another guess, instead of waiting for the truth']] },
    { h: 'The problem', t: 'Monte Carlo waits until the end of a game to learn anything. That is slow, and impossible if the task never ends. Can we learn **after every step**?' },
    { h: 'The core idea', a: "p2_tdCommute", t: 'Guess your commute takes 30 minutes. Halfway, you hit traffic and now expect 40. You update **right away**, without waiting to arrive. That is TD learning.' },
    { h: 'How it works', t: 'After one step, build a better guess: the **reward you just got** plus your estimate for the next state. Move the old estimate a little toward it.', a: 'td' },
    { h: 'The surprise signal', a: "p2_tdAlpha", ctl: [{"k": "a", "l": "α step", "min": 0.02, "max": 1, "step": 0.02, "v": 0.2}], try: "Drag α: big steps chase every surprise, small steps crawl but stay calm.", t: 'The gap between the better guess and the old one is the **TD error**: was that better or worse than I expected? All learning is driven by this surprise.', ex: 'Expected 5, got reward 1 and the next state is worth 6: new guess 7. Surprise is +2, so raise the estimate a bit.' },
    { h: 'TD versus Monte Carlo', t: 'TD learns online and is **less noisy**. The price: its targets lean on its own guesses, so early mistakes can mislead it for a while.' },
    { h: 'Brains do it too', t: 'Dopamine neurons in the brain fire like a TD error. They react to **unexpected** reward, not to reward itself, and go quiet when a promised reward fails to come.' },
    { h: 'What it leads to', t: 'Apply TD to actions instead of states and you get two famous algorithms: **SARSA** and **Q-learning**.' },
  ],
  recap: ['Update after every step, not at the end', 'Target: reward plus next-state guess', 'TD error = surprise signal', 'Less noisy than Monte Carlo, a bit biased'] },

{ id: 'qlearning', title: 'Q-Learning', emoji: '🧩', track: 'Model-free', pre: ['td', 'epsgreedy'],
  hook: 'Learn the value of every move, even while acting randomly.',
  slides: [
    { h: 'Words you’ll need', g: [['Q-value', 'how good it is to take a given action in a given state, then play well'], ['Learning rate', 'how big a step you take toward each new target, often called alpha'], ['TD target', 'reward now plus a guess about the future'], ['Explore', 'try something new to find out how good it is']] },
    { h: 'The goal', t: 'Instead of scoring places, score **moves**. For every state and action, learn one number: how good is it to do this here, then play as well as possible?' },
    { h: 'The update', t: 'After each step, form a target: **reward now plus the best Q-value** in the next state. Move the old Q-value a small step toward it.', a: 'qgrid' },
    { h: 'A worked example', a: "p2_qUpdate", t: 'Q for “right” here is 2. You get reward 1, and the best move in the new square is worth 5. Target: 1 + 0.9 × 5 = 5.5. With a learning rate of 0.1, Q becomes 2.35.' },
    { h: 'Assume the best', t: 'The target uses the **best** next move, even if you actually explore with a random one. So it learns the values of playing perfectly, while you play sloppily.', a: 'bandit', p: { mode: 'eps' } },
    { h: 'A table of numbers', a: "p2_qTable", t: 'Classic Q-learning keeps a table with one number per state and action. Great for small worlds.', ex: 'The Taxi puzzle has 500 states and 6 actions: a 3000-cell table, solved in seconds.' },
    { h: 'The leap', t: 'Replace the table with a **neural network** and you get DQN, which learned to play Atari games straight from the screen pixels in 2015.' },
  ],
  recap: ['One value per state and action', 'Target: reward plus best next Q', 'Learns optimal play while exploring', 'Table version leads to DQN'] },

{ id: 'sarsa', title: 'SARSA', emoji: '🚶', track: 'Model-free', pre: ['td', 'epsgreedy'],
  hook: 'Learn the value of what you’ll actually do next.',
  slides: [
    { h: 'Words you’ll need', g: [['Q-value', 'how good it is to take a given action in a given state'], ['Explore', 'sometimes trying a random move to learn more'], ['On-policy', 'learning about the same behaviour you are actually using']] },
    { h: 'The name', t: 'SARSA is spelled by the five things it uses: **State, Action, Reward**, next **State**, next **Action**, the one you really chose.' },
    { h: 'The update', t: 'Target: reward now plus the Q-value of the **next action you actually take**, not the best one. Then move the old Q-value a small step toward it.' },
    { h: 'Why that matters', a: "p2_cliffEps", ctl: [{"k": "e", "l": "ε random", "min": 0, "max": 0.4, "step": 0.05, "v": 0.1}], try: "Drag ε up: the pink robot falls more and SARSA’s route moves away from the edge.", t: 'If you sometimes take random moves, SARSA’s values **include those mistakes**. It learns how good things are for you, slips and all.' },
    { h: 'Cliff walking', t: 'A path runs along a cliff edge. Q-learning learns the shortest path, right on the edge. SARSA knows it sometimes stumbles, so it learns a **safer detour**.', a: 'cliff' },
    { h: 'An everyday version', t: 'A learner driver keeps extra distance from parked cars, because they know they sometimes swerve. That is SARSA thinking.', ex: 'Expert drivers can cut it close. Learners shouldn’t, yet.' },
    { h: 'When to choose it', a: "p2_cliffEps", ctl: [{"k": "e", "l": "ε random", "min": 0, "max": 0.4, "step": 0.05, "v": 0.2}], try: "Set ε to 0: with no randomness both learn the same short route.", cap: "Count the falls: with random steps, the edge route of Q-learning (pink) costs many falls during learning, while SARSA (teal) stays safe.", t: 'Use SARSA when **mistakes during learning are costly**, like a real robot near stairs. It trades a little speed for safer behaviour while learning.' },
  ],
  recap: ['Target uses the action you really take next', 'On-policy: values include your exploration', 'Learns safer paths near danger'] },

{ id: 'onoff', title: 'On-Policy vs Off-Policy', emoji: '🔀', track: 'Model-free', pre: ['qlearning', 'sarsa'],
  hook: 'Learn only from your own behaviour, or from anyone’s?',
  slides: [
    { h: 'Words you’ll need', g: [['Policy', 'the agent’s rulebook: in this situation, do that'], ['Behaviour policy', 'the rulebook actually used to act and collect data'], ['Target policy', 'the rulebook you are trying to learn and improve']] },
    { h: 'Two roles', t: 'Every learner has **one policy that acts** and gathers experience, and **one policy being learned**. The big question: are they the same?' },
    { h: 'On-policy', t: 'They are the **same**. You learn about exactly what you do, exploration included. SARSA and PPO work this way.', a: 'cliff' },
    { h: 'Off-policy', a: "p2_onOff", t: 'They **differ**. You act one way, maybe randomly, but learn the best possible policy. Q-learning, DQN and SAC work this way.', ex: 'Learning to drive well by watching dashcam videos of other people.' },
    { h: 'Why off-policy is powerful', a: "replay", cap: "Old experiences are stored and pulled out again at random. Only off-policy learners can safely learn from these memories of past behaviour.", t: 'You can **reuse old experience**, learn from humans or other agents, and explore freely without hurting what you learn.' },
    { h: 'Why it is harder', t: 'The data comes from a different policy than the one you’re learning, so it can **mislead**. Corrections and stabilising tricks are needed.', ex: 'Watching a cautious driver tells you little about what happens at high speed.' },
    { h: 'Rule of thumb', t: 'On-policy: simpler and steadier, but needs fresh data constantly. Off-policy: more **data-efficient**, but trickier to keep stable.' },
  ],
  recap: ['Acting policy versus learned policy', 'On-policy: the same one (SARSA, PPO)', 'Off-policy: different, reuses data (Q-learning, DQN)'] },

{ id: 'traces', title: 'Eligibility Traces & TD(λ)', emoji: '✨', track: 'Model-free', pre: ['td', 'mc'],
  hook: 'Give credit to recent steps, fading into the past.',
  slides: [
    { h: 'Words you’ll need', g: [['Credit assignment', 'figuring out which earlier choices caused a later reward'], ['Trace', 'a fading mark left on each state you recently visited'], ['TD(0)', 'TD learning that looks just one step ahead']] },
    { h: 'The problem', t: 'A reward arrives. Which earlier steps deserve the credit? One-step TD credits only the **last** step. Monte Carlo credits **all** of them equally.' },
    { h: 'The core idea', a: "p2_lambda", p: {"fp": 1}, cap: "Footprints behind the robot fade step by step. When the reward arrives, fresher footprints get more of the credit (green).", t: 'Like footprints in snow that slowly fill in. Each state you visit gets a mark, a **trace**, that fades a little every step.' },
    { h: 'How it works', t: 'When a reward or surprise arrives, every state gets updated **in proportion to its trace**. Recent states change a lot, old ones barely.', a: 'traces' },
    { h: 'The dial λ', a: "p2_lambda", ctl: [{"k": "l", "l": "λ", "min": 0, "max": 1, "step": 0.05, "v": 0.8}], try: "Drag λ to 0: only the last square gets credit. At 1, all squares share it.", t: 'λ (lambda), a number from 0 to 1, sets how slowly traces fade. **0 means one-step TD. 1 means Monte Carlo.** Values in between often learn fastest.', ex: 'λ = 0.9: a state visited 5 steps ago still gets about 0.6 of the credit, before discounting.' },
    { h: 'A famous success', t: 'TD-Gammon, built by Gerald Tesauro in 1992, used TD(λ) and self-play to reach world-class **backgammon**.' },
    { h: 'An everyday version', t: 'After winning a game, you remember the last few moves that sealed it more vividly than your opening. That fading memory is an eligibility trace.' },
  ],
  recap: ['Traces mark recently visited states', 'A reward updates states by their trace', 'λ slides between one-step TD and Monte Carlo'] },

{ id: 'funcapprox', title: 'Function Approximation', emoji: '🕸️', track: 'Deep RL', pre: ['values'],
  hook: 'Too many states for a table? Learn a function that generalises.',
  slides: [
    { h: 'Words you’ll need', g: [['Function', 'a recipe that turns inputs into an output number'], ['Features', 'useful measurements describing a state, like distance or speed'], ['Neural network', 'a flexible function with many adjustable knobs, tuned from data'], ['Generalise', 'use what you learned on some cases to handle new similar ones']] },
    { h: 'Tables don’t scale', t: 'A value table needs one entry per state. Camera images, robot joints, Go boards: there are far **too many states**, and most are never seen twice.' },
    { h: 'The core idea', t: 'Instead of memorising every state, learn a **function** that predicts value from the state’s description. Learning about one state then teaches you about similar ones.', a: 'funcApprox' },
    { h: 'An everyday version', a: "p2_fit", try: "Tap the chart to add a house; the line refits and the 🏠? price changes.", t: 'You don’t memorise the price of every house. You learn a rule of thumb: bigger and closer to the city means more expensive. That rule works on houses you’ve never seen.' },
    { h: 'Features', t: 'The function reads **features** of the state. They can be hand-made, like distance to goal, or learned automatically by a deep network from raw pixels.', ex: 'Cart-pole: cart position, cart speed, pole angle, pole spin.' },
    { h: 'How it learns', t: 'Each time you get a better target value, nudge the function’s knobs so its prediction for that state moves a little **toward the target**.' },
    { h: 'The catch', a: "p2_fit", p: {"mode": "rbf"}, try: "Tap anywhere to set a target and see neighbours move too.", cap: "The pink curve is the learned value across many states. Training it toward one gold target also drags the nearby part of the curve: grey dashed shows how it was before.", t: 'Changing the function for one state also changes many others. Mixed with guess-based targets and off-policy data, learning can blow up: the **deadly triad**.', ex: 'Fixing one prediction shifts its neighbours, which shifts the targets, which shifts everything again.' },
  ],
  recap: ['Replace tables with a learned function', 'Generalises to states never seen', 'Features describe states', 'Beware the deadly triad'] },

{ id: 'dqn', title: 'Deep Q-Network (DQN)', emoji: '👾', track: 'Deep RL', pre: ['qlearning', 'funcapprox'],
  hook: 'Q-learning plus a neural network: superhuman Atari from pixels.',
  slides: [
    { h: 'Words you’ll need', g: [['Q-value', 'how good it is to take an action in a state, then play well'], ['Neural network', 'a flexible function with many adjustable knobs, tuned from data'], ['Pixels', 'the tiny coloured dots that make up a screen image']] },
    { h: 'The problem', t: 'Q-learning needs a table, one number per state and action. An Atari screen has **astronomically many** possible images. No table could ever hold them.' },
    { h: 'The core idea', t: 'Let a **neural network** read the game screen and output one Q-value per joystick action. Then pick the action with the highest score.', a: 'dqn' },
    { h: 'The 2015 milestone', t: 'DeepMind used one algorithm, with the same settings, on **49 Atari games**, learning only from pixels and the score. It beat human level on many of them.' },
    { h: 'Seeing motion', a: "p2_frames", t: 'One frame can’t show which way the ball moves. So DQN feeds the **last 4 frames** together, letting the network see motion.', ex: 'In Breakout, a single frame can’t tell you whether the ball is rising or falling.' },
    { h: 'Why naive training fails', a: "p2_buffer", cap: "Tiles are experiences coloured by moment. Training on the latest few in order means a batch of nearly identical moments; a random batch from memory is varied.", t: 'Back-to-back frames are nearly identical, so the network overfits to the moment. And its targets shift every time it learns: **unstable**.' },
    { h: 'Two key tricks', t: '**Experience replay** shuffles old memories to break the patterns. A **target network** holds the targets still for a while. Each gets its own reel.' },
  ],
  recap: ['Neural net outputs a Q-value per action', 'Learned 49 Atari games from pixels (2015)', 'Stacks 4 frames to see motion', 'Needs replay and a target network'] },

{ id: 'replay', title: 'Experience Replay', emoji: '📼', track: 'Deep RL', pre: ['dqn'],
  hook: 'Store experiences, then learn from random old memories.',
  slides: [
    { h: 'Words you’ll need', g: [['Transition', 'one step of experience: state, action, reward, next state'], ['Buffer', 'a big memory that stores past transitions'], ['Minibatch', 'a small random handful of examples used for one training update'], ['Correlated', 'samples so alike that they teach the same thing again and again']] },
    { h: 'The problem', t: 'Learning from steps in the order they happen is like studying only the last page you read. Consecutive frames are **nearly identical**, and old lessons get forgotten.' },
    { h: 'The core idea', t: 'Keep a **diary of experiences**. Every step, write down what you saw, did, got, and where you ended up.', a: 'replay' },
    { h: 'How it works', t: 'Store each transition in a big buffer, like the last **1 million steps**. To train, pull out a random **minibatch** of, say, 32, and learn from those.' },
    { h: 'Why it helps', a: "p2_buffer", t: 'Random picks **break the correlation** between samples. And each experience gets reused many times, so you need far fewer steps in the world.', ex: 'A rare crash in a driving game gets replayed many times, instead of seen once and forgotten.' },
    { h: 'Prioritised replay', a: "p2_buffer", p: {"mode": "prio"}, ctl: [{"k": "pr", "l": "priority", "min": 0, "max": 1, "step": 0.1, "v": 0.6}], try: "Drag priority to 0: every memory is replayed equally often.", cap: "Ten stored memories. Red bars show how surprising each was, teal bars count how often it was replayed. More priority means surprising ones get picked far more.", t: 'An upgrade: replay **surprising** transitions, the ones with a big TD error, more often than boring ones.', ex: 'Like re-reading the exam questions you got wrong rather than the easy ones.' },
    { h: 'The limit', t: 'Old memories came from an older version of the agent. That’s fine for off-policy methods like DQN, but **on-policy methods** like PPO can’t use a big replay buffer.' },
  ],
  recap: ['Store transitions in a big buffer', 'Train on random minibatches', 'Breaks correlation and reuses data', 'Works for off-policy methods'] },

{ id: 'targetnet', title: 'Target Networks', emoji: '🎯', track: 'Deep RL', pre: ['dqn'],
  hook: 'Stop chasing your own tail: freeze the target for a while.',
  slides: [
    { h: 'Words you’ll need', g: [['TD target', 'reward now plus a guess about the future, used as the answer to learn toward'], ['Weights', 'the adjustable numbers inside a neural network'], ['Copy', 'a second network with the same weights as the first']] },
    { h: 'The problem', t: 'In DQN, the target the network learns toward is computed by **the same network**. Every update moves the target too, so you chase your own tail.' },
    { h: 'An everyday version', t: 'Imagine aiming at a dartboard that jumps every time you throw. Hitting a board that **stays put** for a minute is much easier.' },
    { h: 'The fix', t: 'Keep a second, **frozen copy** of the network just for computing targets. Train the main network toward those steady targets.', a: 'target' },
    { h: 'Refreshing the copy', a: "p2_chase", ctl: [{"k": "N", "l": "copy every N", "min": 1, "max": 30, "step": 1, "v": 1}], try: "Drag N up from 1: the gold target becomes stairs and pink stops wobbling.", t: 'Every N steps, say **every 10,000**, copy the main network’s weights into the frozen one. Then the targets hold still again until the next copy.' },
    { h: 'Soft updates', a: "p2_chase", p: {"mode": "soft"}, ctl: [{"k": "tau", "l": "blend τ", "min": 0.005, "max": 0.5, "step": 0.005, "v": 0.05}], try: "Drag τ: tiny values give a smooth target, large ones a jumpy one.", cap: "Gold is a slowly blended copy of the network that provides targets, pink is the network. A small blend keeps the target smooth but slower to catch up.", t: 'Another option: every step, blend the copy slowly toward the main network, like **99.5% old, 0.5% new**. DDPG and SAC use this.', ex: 'The target drifts smoothly instead of jumping.' },
    { h: 'Why it works', t: 'It turns one endless chase into a series of **short, fixed** learning problems. Training becomes much more stable.' },
  ],
  recap: ['Targets come from a lagging copy', 'Copy every N steps, or blend slowly', 'Much steadier training'] },
// part 3
{ id: 'doubledqn', title: 'Double DQN', emoji: '👯', track: 'Deep RL', pre: ['dqn'],
  hook: 'Taking a max over noisy guesses is too optimistic.',
  slides: [
    { h: 'Words you’ll need', g: [['Q-value', 'a guess of the total future reward for taking an action in a situation'], ['DQN', 'a neural network that learns Q-values, famous for playing Atari games'], ['Target network', 'a slowly updated copy of the network, used to compute learning targets'], ['Bias', 'a mistake that leans the same way every time, not random noise']] },
    { h: 'The problem', a: "p3_maxNoise", ctl: [{"k": "sig", "l": "noise", "min": 0, "max": 2, "step": 0.1, "v": 1}, {"k": "n", "l": "actions", "min": 2, "max": 10, "step": 1, "v": 6}], try: "Raise the noise or add actions and watch the pink average climb.", t: 'DQN learns by asking: what is the **best** next action worth? It answers by taking the **max** over its own Q-value guesses. But those guesses are noisy, and the max loves noise.' },
    { h: 'Why the max is optimistic', t: 'Imagine ten actions that are all truly worth 0. Your guesses are 0 plus random errors. The biggest guess is almost always **above zero**, so you overestimate by pure luck.', a: 'overest', ex: 'Ten people guess the weight of a cow. The highest guess is almost always too high.' },
    { h: 'It snowballs', a: "p3_snowball", t: 'That too-high number becomes the learning target for the previous step, which feeds the step before it. The **overestimation spreads** backwards and can make the agent chase actions that only look good.' },
    { h: 'The fix in plain words', t: 'Split the job in two. One network **chooses** which next action looks best. A different network **scores** that choice. Their errors don’t line up, so the lucky spike gets cancelled out.' },
    { h: 'A tiny example', t: 'The online network says action B looks best, at 5.2. The target network scores B at only 3.1. Double DQN learns from **3.1**, not 5.2, giving a calmer, more honest target.', ex: 'Asking one friend to pick the restaurant and another friend to rate it.' },
    { h: 'Almost free', t: 'DQN already keeps two networks, the online one and the target copy. So Double DQN is basically a **one-line change**. It came from Hado van Hasselt’s Double Q-learning, scaled up to deep networks in 2015.' },
    { h: 'Same idea, everywhere', t: 'Continuous-control methods like TD3 and SAC keep **two critics** and trust the **lower** of their two guesses. Different trick, same goal: stop the max from fooling itself.', ex: 'Getting two quotes for a repair and planning around the cheaper, more cautious one.' },
  ],
  recap: ['A max over noisy guesses is too optimistic', 'Errors spread backwards through targets', 'Choose with one net, score with the other', 'TD3 and SAC use the min of two critics'] },

{ id: 'pg', title: 'Policy Gradient Methods', emoji: '📐', track: 'Policy Gradients', pre: ['policy'],
  hook: 'Skip the values: directly tweak the policy to win more.',
  slides: [
    { h: 'Words you’ll need', g: [['Policy', 'the agent’s rule for picking an action in each situation'], ['Parameters', 'the adjustable numbers inside a model, like knobs'], ['Gradient', 'the direction to turn the knobs to make a number go up fastest'], ['Return', 'the total reward collected from now until the end']] },
    { h: 'A different route', t: 'Many methods first learn how good each action is, then pick the best. **Policy gradient** methods skip that middle step and adjust the **policy itself** to collect more reward.' },
    { h: 'The policy as a dial board', a: "p3_dials", try: "Tap a column to turn its dial up; tap reset to start over.", t: 'Make the policy a neural network with **parameters** that outputs a **probability** for each action. Learning means nudging those numbers so good actions get likelier.' },
    { h: 'The core intuition', t: 'Try something. If things went **better** than usual, make those actions **more likely**. If worse, make them less likely. Repeat thousands of times.', a: 'pg', ex: 'A basketball player who drifts toward shots that tend to go in.' },
    { h: 'A tiny example', a: "p3_pgLR", ctl: [{"k": "lr", "l": "step size", "min": 0.05, "max": 1.5, "step": 0.05, "v": 0.3}], try: "Drag the step size: big steps learn fast but jump around.", t: 'The policy picks left 50% and right 50%. Going right earns a big reward. After a small update it might pick right **55%** of the time. Many small steps add up.' },
    { h: 'Why bother?', t: 'It handles **continuous actions** naturally: just output a number, like a steering angle. It can also learn deliberately random policies, which matter in games against opponents.', ex: 'A robot arm choosing a torque of 0.37. There is no table of every possible torque.' },
    { h: 'The catch', t: 'The signal is **noisy**. One lucky episode can push the policy the wrong way, so it needs many samples. A lot of later ideas, like baselines and critics, exist to calm that noise.' },
  ],
  recap: ['Adjust the policy directly, not values', 'Good outcomes make those actions likelier', 'Natural for continuous actions', 'Noisy, so needs many samples'] },

{ id: 'reinforce', title: 'REINFORCE', emoji: '🏋️', track: 'Policy Gradients', pre: ['pg', 'mc'],
  hook: 'The simplest policy gradient: weight actions by the episode’s return.',
  slides: [
    { h: 'Words you’ll need', g: [['Episode', 'one complete run, from start to finish, like one game'], ['Return', 'the total reward collected from a step until the episode ends'], ['Monte Carlo', 'learning from the real outcomes of complete episodes'], ['Variance', 'how much results jump around from one try to the next']] },
    { h: 'The idea in one line', t: 'Play a whole **episode**. Then, for every action you took, make it more likely in proportion to the **return** that came after it. That’s the whole algorithm.' },
    { h: 'Step by step', t: 'One: play an episode with the current policy. Two: for each step, add up the rewards that followed. Three: nudge each action’s probability up by an amount **scaled by that total**.', a: 'reinforce' },
    { h: 'A tiny example', a: "p3_creditTiles", t: 'An episode has three moves and ends with a reward of 10. Each move gets credit 10, so all three become a bit **more likely**. An episode ending in minus 5 pushes its moves down.' },
    { h: 'Honest but noisy', a: "p3_noisyG", ctl: [{"k": "n", "l": "episodes", "min": 1, "max": 50, "step": 1, "v": 1}], try: "Average more episodes and watch the pink arrow settle.", t: 'It uses **real** outcomes, so on average it points the right way. But one episode’s luck colours every action in it, so the updates have **high variance**.', ex: 'A winning chess game makes every move in it likelier, even the blunder the opponent failed to punish.' },
    { h: 'Where it came from', t: 'Ronald **Williams** introduced REINFORCE in **1992**. It is still used today, for example to fine-tune text generators against a reward score.' },
    { h: 'Taming the noise', t: 'Two fixes lead to the next reels. Subtract a **baseline**, so only better-than-usual returns push actions up. Or replace the real return with a learned **critic**, giving actor-critic.' },
  ],
  recap: ['Play an episode, then credit every action', 'Credit = the return that followed', 'Unbiased but very noisy', 'Baselines and critics reduce the noise'] },

{ id: 'baseline', title: 'Baselines & Advantage', emoji: '⚖️', track: 'Policy Gradients', pre: ['reinforce', 'values'],
  hook: 'Not “was it good?” but “was it better than usual?”',
  slides: [
    { h: 'Words you’ll need', g: [['Return', 'the total reward collected from a step until the episode ends'], ['Value V(s)', 'the return you expect on average from a situation'], ['Baseline', 'a reference score you compare each outcome against'], ['Advantage', 'how much better an action did than the usual outcome']] },
    { h: 'The problem', a: "p3_baseB", ctl: [{"k": "b", "l": "baseline", "min": 0, "max": 150, "step": 5, "v": 0}], try: "Drag the baseline to about 100: only A keeps getting pushed up.", t: 'Suppose every episode scores around **plus 100**. Plain REINFORCE then pushes **every** action up, good or bad. The useful signal, which actions did slightly better, is buried.' },
    { h: 'Compare to normal', t: 'Instead of asking “was this good?”, ask “was this **better than usual**?” Subtract a **baseline** from each return, and only the difference drives learning.', a: 'baseline', ex: 'Grading on a curve: 75 is great if the class average is 60, and poor if it is 90.' },
    { h: 'A tiny example', t: 'From some situation you normally get 100. This time you got 104, so the action gets plus 4: a gentle push up. Another time you got 95, so minus 5: a gentle push **down**.' },
    { h: 'The best baseline', t: 'A natural baseline is **V(s)**, the return you usually get from that situation. A second network can learn it alongside the policy.' },
    { h: 'Advantage', a: "p3_advantage", t: 'Return minus baseline has a name: the **advantage**. It says how much better this action did than the policy’s average from here. Positive means do it more, negative means less.' },
    { h: 'No free lunch? Almost', t: 'As long as the baseline doesn’t depend on which action you took, it doesn’t change the **average direction** of learning. It only removes noise, so learning gets **much faster**.' },
  ],
  recap: ['Raw returns push every action up', 'Subtract a baseline: better than usual?', 'Advantage = return minus expected value', 'Same direction, far less noise'] },

{ id: 'actorcritic', title: 'Actor-Critic', emoji: '🎭', track: 'Policy Gradients', pre: ['baseline', 'td'],
  hook: 'One network acts, another grades every move.',
  slides: [
    { h: 'Words you’ll need', g: [['Policy', 'the agent’s rule for picking an action in each situation'], ['Value function', 'a learned guess of how much reward lies ahead from a situation'], ['TD error δ', 'the surprise: how much better or worse a step went than predicted'], ['Online learning', 'updating after every step instead of waiting for the episode to end']] },
    { h: 'Two roles', t: 'The **actor** is the policy: it chooses what to do. The **critic** is a value function: it judges how good the situation is. They learn together.', a: 'actorCritic' },
    { h: 'An analogy', t: 'An athlete and a coach. The athlete tries a move, the coach immediately says “**better** than I expected” or “**worse**”. The athlete adjusts, and the coach keeps refining their judgement too.' },
    { h: 'How one step works', a: "p3_tdStep", t: 'The actor acts and gets a reward. The critic compares its prediction with reward plus its guess for the next state. The gap is the **TD error δ** (delta). Positive δ: do that more.', ex: 'Critic expected 10. You got reward 2 and the next state looks worth 9. That is 11, so δ = plus 1.' },
    { h: 'Why it helps', t: 'REINFORCE waits for the episode to end and is very noisy. Actor-critic learns **every step** and uses the critic’s steadier estimate, so it’s usually **faster and calmer**.' },
    { h: 'The trade-off', a: "p3_darts", t: 'The critic is only a guess. If it’s wrong, it can steer the actor wrong. That adds a bit of **bias** in exchange for much less noise, a trade most modern methods happily make.' },
    { h: 'A big family', t: 'A2C, A3C, PPO, DDPG, TD3 and SAC are all **actor-critic** methods. Most of today’s deep RL, from game agents to robot controllers, works this way.' },
  ],
  recap: ['Actor picks actions, critic judges them', 'TD error tells the actor better or worse', 'Learns every step, less noisy', 'Basis of PPO, SAC, TD3 and more'] },

{ id: 'gae', title: 'n-step Returns & GAE', emoji: '🎚️', track: 'Policy Gradients', pre: ['actorcritic', 'traces'],
  hook: 'How far should you look before trusting the critic’s guess?',
  slides: [
    { h: 'Words you’ll need', g: [['Critic', 'a learned guess of how much reward lies ahead from a situation'], ['Bootstrapping', 'using your own guess of the future instead of waiting to see it'], ['Bias', 'a mistake that leans the same way every time'], ['Variance', 'how much results jump around from one try to the next']] },
    { h: 'The question', t: 'To judge an action, you can wait and add up **real rewards**, or stop early and trust the **critic’s guess** for the rest. How many real steps should you look at first?' },
    { h: 'n-step returns', a: "p3_nstepN", ctl: [{"k": "n", "l": "n", "min": 1, "max": 8, "step": 1, "v": 3}], try: "Slide n from 1 to 8 and compare the estimate with the truth.", t: 'Add up the next **n** real rewards, then plug in the critic’s estimate for everything after. With n equal to 1 you lean almost fully on the critic; with large n, mostly on reality.', ex: 'n = 3: reward 1, reward 0, reward 2, then the critic says 7 is left. Total about 10.' },
    { h: 'The trade-off', a: "p3_darts", cap: "Each dot is one estimate and the gold centre is the truth. Pink: long n-step returns, centred but scattered. Teal: one-step returns that lean on the critic, tight but off-centre.", t: 'Small n: steady, **low variance**, but wrong if the critic is wrong, which is **bias**. Large n: right on average, but noisy because many random rewards pile up.' },
    { h: 'GAE: mix them all', t: '**Generalised Advantage Estimation** doesn’t pick one n. It blends all of them, giving nearer ones more weight. A single knob, **λ** (lambda) between 0 and 1, sets how fast the weights fade.', a: 'nstep' },
    { h: 'Turning the knob', a: "p3_gaeKnob", ctl: [{"k": "lam", "l": "λ", "min": 0, "max": 1, "step": 0.01, "v": 0.95}], try: "Drag λ from 0 to 1 and watch the dots tighten or spread.", t: 'λ = 0 means trust the critic after one step. λ = 1 means use the full real return. Values in between give a smooth **middle ground**.', ex: 'Like advice: trust your own eyes for the next few steps, and a forecast for the far future.' },
    { h: 'In practice', t: 'GAE was introduced by John Schulman and colleagues in 2015. **λ = 0.95** is the near-universal default in PPO, and it’s one reason PPO trains so reliably.' },
  ],
  recap: ['n-step: n real rewards, then the critic', 'Small n biased, large n noisy', 'GAE blends every n with one knob λ', 'Default λ about 0.95 in PPO'] },

{ id: 'ppo', title: 'PPO', emoji: '🛡️', track: 'Policy Gradients', pre: ['actorcritic'],
  hook: 'Improve the policy, but not too much at once.',
  slides: [
    { h: 'Words you’ll need', g: [['Policy', 'the agent’s rule for picking an action in each situation'], ['Update', 'one round of changing the network’s numbers to improve it'], ['Batch', 'a chunk of collected experience used for training together'], ['Ratio', 'new probability of an action divided by its old probability']] },
    { h: 'The danger', a: "p3_cliffStep", ctl: [{"k": "step", "l": "step size", "min": 0.1, "max": 2, "step": 0.05, "v": 0.4}], try: "Push the step size up until the agent jumps off the cliff.", t: 'Policy gradient steps are noisy. One **too-big update** can wreck a good policy. Worse, the broken policy then collects bad data, so it can be hard to ever recover.' },
    { h: 'The idea', t: 'Improve the policy, but keep each new version **close to the old one**. Small, safe steps, many times. That’s **Proximal** Policy Optimization: proximal means nearby.' },
    { h: 'Clip the ratio', t: 'For each action, compare its new probability with the old one: the **ratio**. If it drifts beyond a band, typically 0.8 to 1.2, PPO **stops pushing** further in that direction.', a: 'ppoClip', ex: 'An action had 10% chance. PPO will happily move it to 12%, but gets no extra credit for 30%.' },
    { h: 'Reuse data safely', a: "p3_ppoEpochs", ctl: [{"k": "eps", "l": "clip ε", "min": 0.05, "max": 0.5, "step": 0.05, "v": 0.2}], try: "Change ε: the teal bar may only move inside the gold band.", t: 'Because of the clip, PPO can take **several passes** over the same batch of experience without going off the rails. That squeezes more learning out of each game played.' },
    { h: 'Its ancestor, TRPO', t: '**Trust Region Policy Optimization**, from 2015, enforced the same small-step rule with heavier maths. PPO, from 2017, gets most of the benefit with a much simpler trick.' },
    { h: 'Everywhere', t: 'PPO became the default for game agents, simulated robots, and the reinforcement step of RLHF for chatbots. **OpenAI Five**, which beat world champions at Dota 2, was trained with PPO.' },
  ],
  recap: ['Big policy updates can wreck performance', 'Keep the new policy close to the old', 'Clipped probability ratio does it simply', 'Default for games, robots and RLHF'] },

{ id: 'sac', title: 'Entropy & Soft Actor-Critic', emoji: '🌈', track: 'Policy Gradients', pre: ['actorcritic', 'explore'],
  hook: 'Reward the agent for keeping its options open.',
  slides: [
    { h: 'Words you’ll need', g: [['Entropy', 'a measure of how random or spread out choices are'], ['Off-policy', 'able to learn from old experience, even from a different behaviour'], ['Critic', 'a learned guess of how much reward lies ahead'], ['Continuous control', 'tasks where actions are smooth numbers, like motor torques']] },
    { h: 'Entropy', t: '**Entropy** measures how spread out a policy’s choices are. Always picking the same action means low entropy. Spreading bets across many actions means **high** entropy.', a: 'entropy', ex: 'A fair die has high entropy. A die that always lands on six has zero.' },
    { h: 'A new goal', a: "p3_softTemp", ctl: [{"k": "alpha", "l": "α", "min": 0.05, "max": 3, "step": 0.05, "v": 0.5}], try: "Drag α: small means greedy, large means spread out.", t: 'Maximum-entropy RL asks the agent to collect reward **and** stay as random as it can while doing so. Score = reward + **α** (alpha) × entropy. Alpha sets how much randomness is worth.' },
    { h: 'Why that helps', t: 'Built-in **exploration**: the agent keeps trying alternatives. It also avoids collapsing early onto one mediocre trick, and copes better when the world nudges it off course.' },
    { h: 'An analogy', a: "p3_routes", t: 'Learning several routes to work, not just one. You still take a fast route, but when a road is closed you already know a **backup**.' },
    { h: 'Soft Actor-Critic', t: '**SAC** puts this into an actor-critic. It learns **off-policy** from a memory of old experience, uses two critics and trusts the lower one, and tunes α automatically.' },
    { h: 'Where it shines', t: 'SAC, from Tuomas Haarnoja and colleagues in 2018, is a go-to for **continuous control**. It taught a real four-legged robot to walk from about **two hours** of real experience.' },
  ],
  recap: ['Entropy = how random the policy is', 'Goal: reward plus α times entropy', 'Built-in exploration and robustness', 'SAC: stable off-policy continuous control'] },

{ id: 'ddpg', title: 'Continuous Control: DDPG & TD3', emoji: '🦿', track: 'Policy Gradients', pre: ['actorcritic', 'dqn'],
  hook: 'DQN for steering wheels and robot joints.',
  slides: [
    { h: 'Words you’ll need', g: [['Continuous action', 'an action that is any number in a range, like 0.37'], ['Q-value', 'a guess of the total future reward for an action in a situation'], ['Replay buffer', 'a memory of past experience the agent learns from again'], ['Target network', 'a slowly updated copy of a network, used for steady learning targets']] },
    { h: 'The problem', t: 'DQN picks the action with the **highest** Q-value by checking every option. With a steering wheel there are **infinitely many** angles, so checking each one is impossible.' },
    { h: 'Learn the best action', t: 'Train an **actor** network that outputs a single action directly. It learns by asking the critic: which small change to my action would **raise the Q-value**? Then it moves that way.', a: 'continuous' },
    { h: 'Like climbing a hill', a: "p3_hillTap", try: "Tap anywhere along the curve to drop the actor there.", t: 'Picture the critic’s Q-values as a hilly landscape over all possible actions. The actor is a hiker always stepping **uphill**, toward the best action for each situation.', ex: 'Steering 0.30 scores 5, steering 0.32 scores 5.4. The actor shifts toward 0.32.' },
    { h: 'DDPG', t: '**Deep Deterministic Policy Gradient**, from 2015, combined this with DQN’s tricks: a **replay buffer**, **target networks**, and random noise added to actions so it keeps exploring.' },
    { h: 'TD3 fixes it', a: "p3_twinCritics", t: 'DDPG overestimated Q-values and was fragile. **TD3**, from 2018, keeps **two critics** and trusts the lower, updates the actor less often, and smooths its targets. Much more reliable.' },
    { h: 'Where it’s used', t: 'Classic benchmarks are simulated robots like **HalfCheetah** and **Hopper** in MuJoCo, plus robot arms. TD3 and SAC are the usual starting points for these tasks today.' },
  ],
  recap: ['Can’t check every continuous action', 'Actor climbs the critic’s Q landscape', 'Reuses replay and target networks', 'TD3 adds twin critics and delays'] },

{ id: 'modelbased', title: 'Model-Based RL', emoji: '🔮', track: 'Model-based', pre: ['mdp', 'values'],
  hook: 'Learn how the world works, then plan in your head.',
  slides: [
    { h: 'Words you’ll need', g: [['Model', 'a predictor of what happens next if you take an action'], ['Planning', 'trying out actions in your head before doing them for real'], ['Rollout', 'a chain of imagined steps, one after another'], ['Sample efficiency', 'how much a method learns from each bit of real experience']] },
    { h: 'Two ways to learn', t: 'Model-free agents learn purely by trial and error. **Model-based** agents also learn **how the world works**, then use that knowledge to think ahead.' },
    { h: 'What a model is', a: "p3_modelLearn", t: 'A **model** predicts the **next state and reward** for a given state and action. Sometimes it’s given, like the rules of chess. Often it has to be learned from data.', ex: 'A thermostat model: heater on for 10 minutes, room goes from 18 to 20 degrees.' },
    { h: 'Plan before acting', t: 'With a model you can **imagine**: if I do this, then that, where do I end up? Try many options in your head, then do the most promising one for real.', a: 'modelBased' },
    { h: 'Why it’s attractive', t: 'Imagined experience is **free**. Real experience with robots, patients or expensive machines is slow and costly. A good model can cut the real data needed **dramatically**.' },
    { h: 'An old idea', t: 'Richard Sutton’s **Dyna**, from 1990, learned a model and mixed real updates with imagined ones. The same spirit runs through modern systems like MuZero and Dreamer.' },
    { h: 'The pitfall', a: "p3_compound", ctl: [{"k": "err", "l": "model error", "min": 0, "max": 0.25, "step": 0.01, "v": 0.08}], try: "Set the error to 0, then raise it, and watch the red gap.", t: 'Small model errors **snowball** over long imagined rollouts. Worse, a planner will happily exploit any mistake that promises fake reward. Short rollouts and uncertainty estimates help.', ex: 'A sat-nav with one wrong road confidently routes you into a lake.' },
  ],
  recap: ['A model predicts next state and reward', 'Plan by imagining before acting', 'Saves costly real experience', 'Model errors compound and get exploited'] },

{ id: 'mcts', title: 'Monte Carlo Tree Search', emoji: '🌳', track: 'Model-based', pre: ['modelbased', 'ucb'],
  hook: 'Grow a search tree toward the most promising moves.',
  slides: [
    { h: 'Words you’ll need', g: [['Search tree', 'a map of possible moves, then replies, then replies to those'], ['Node', 'one position in the tree'], ['Playout', 'a quick game played to the end, often with random moves'], ['UCB', 'a rule that favours good-looking or rarely tried options']] },
    { h: 'The problem', t: 'In Go there are about **250** legal moves per turn. Looking even a few moves ahead creates more positions than you could ever check. You need to search **selectively**.' },
    { h: 'Four steps, repeated', t: '**Select**: walk down the tree using UCB. **Expand**: add a new position. **Simulate**: play it out quickly. **Back up**: send the result back up the path.', a: 'mcts' },
    { h: 'A tiny example', a: "p3_mctsTap", try: "Tap to run playouts and see which move UCB picks next.", t: 'Move A has won 6 of 10 playouts, move B 1 of 2. UCB might still try B, because 2 tries is too few to judge. Each loop, the counts update and the tree **grows**.' },
    { h: 'Lopsided on purpose', a: "mcts", cap: "Watch where the tree grows: most new nodes, and the highest visit counts, pile up under the branch that keeps winning, while weak branches stay short.", t: 'The tree grows **deep** where moves look good and stays shallow elsewhere. Effort goes where it matters, instead of searching everything equally.', ex: 'Like a detective spending most time on the most promising leads.' },
    { h: 'Stop anytime', t: 'MCTS is **anytime**: halt whenever time runs out and play the move that was **visited most** at the top of the tree. More thinking time simply gives better moves.' },
    { h: 'Where it shines', t: 'MCTS took off around **2006** and transformed computer Go. It sits at the heart of **AlphaGo**, which beat Lee Sedol in 2016, and is used in puzzle solving and planning.' },
  ],
  recap: ['Select, expand, simulate, back up', 'Focuses effort on promising moves', 'Anytime: more thinking, better moves', 'The search engine behind AlphaGo'] },

{ id: 'alphazero', title: 'AlphaZero', emoji: '♟️', track: 'Model-based', pre: ['mcts', 'actorcritic'],
  hook: 'Self-play + tree search + one neural network.',
  slides: [
    { h: 'Words you’ll need', g: [['Self-play', 'an agent learning by playing games against copies of itself'], ['MCTS', 'a search that grows a tree of moves toward promising ones'], ['Policy head', 'the part of the network that suggests likely good moves'], ['Value head', 'the part of the network that guesses who is winning']] },
    { h: 'Starting from zero', t: 'AlphaZero is given **only the rules** of the game. No human games, no opening books, no expert tips. Everything it knows, it learns by playing **against itself**.' },
    { h: 'The loop', t: 'Play many games against itself using tree search. Train the network on those games. Use the improved network to play the next batch. **Repeat**.', a: 'selfplay' },
    { h: 'One network, two heads', a: "p3_twoHeads", t: 'A single network looks at a position and outputs two things. The **policy head** suggests which moves are worth searching. The **value head** estimates who is likely to **win**.' },
    { h: 'Search as a teacher', a: "p3_searchTeacher", t: 'Tree search guided by the network finds **better moves** than the network alone. The network is then trained to **imitate** those search results, so each round it gets stronger.', ex: 'A student checks answers with careful working, then learns to get them right at a glance.' },
    { h: 'Results', t: 'DeepMind’s AlphaZero, in **2017**, reached superhuman play at **chess, shogi and Go**. In chess it overtook the top engine Stockfish after only hours of self-play training.' },
    { h: 'What came next', t: '**MuZero**, from 2019, went further: it isn’t even told the rules. It learns its own model of the game and plans with it, and also mastered Atari games.' },
  ],
  recap: ['Learns from the rules alone, via self-play', 'Network guides search, search trains network', 'Superhuman at chess, shogi and Go', 'MuZero learned the rules too'] },
// part 4
{ id: 'worldmodels', title: 'World Models & Dreamer', emoji: '💭', track: 'Model-based', pre: ['modelbased', 'funcapprox'],
  hook: 'Learn to dream the game, then practise inside the dream.',
  slides: [
    { h: 'Words you’ll need', g: [['Model', 'the agent’s own learned guess of what the world does next'], ['Latent state', 'a short list of numbers that summarises what the agent sees'], ['Rollout', 'playing out a sequence of steps, one after another'], ['Policy', 'the agent’s rule for picking an action in each situation']] },
    { h: 'The problem', t: 'Real experience is **expensive**. A robot needs hours, a game needs millions of frames. What if the agent could practise in its head instead?', ex: 'A pilot trains in a flight simulator before flying a real plane.' },
    { h: 'Dream a little', t: 'A **world model** is a learned simulator. It watches real play and learns to predict what happens next after each action.' },
    { h: 'Squeeze the picture', t: 'Predicting every pixel is wasteful. So the model first compresses each image into a small **latent state**, then learns how that summary changes.', a: 'worldModel' },
    { h: 'Practise in imagination', a: "p4_dream", t: 'The policy is then trained on **imagined rollouts**: thousands of dreamed futures inside the model, which cost almost nothing to run.', ex: 'Collect 1 hour of real play, then dream 100 hours of practice from it.' },
    { h: 'Why the summary works', t: 'You only need to predict what matters for **reward**. The details that never change the outcome can be thrown away.', ex: 'You can imagine catching a ball without picturing every blade of grass.' },
    { h: 'Famous examples', t: '**World Models** (2018) learned car racing inside its own dream. **DreamerV3** (2023) used one set of settings across many tasks and collected diamonds in Minecraft from scratch.' },
    { h: 'The catch', a: "p4_modelError", ctl: [{"k": "err", "l": "model error", "min": 0, "max": 0.3, "step": 0.01, "v": 0.08}], try: "Drag the error slider: even small errors grow far ahead.", t: 'If the dream is wrong, the agent learns tricks that only work in the dream. So these methods keep checking the model against fresh real experience.' },
  ],
  recap: ['A world model is a learned simulator', 'It works on a compact latent summary', 'Train the policy on imagined rollouts', 'Watch out for flaws in the dream'] },

{ id: 'shaping', title: 'Reward Shaping', emoji: '🧲', track: 'Rewards', pre: ['returns', 'explore'],
  hook: 'Add hints so the agent isn’t searching in the dark.',
  slides: [
    { h: 'Words you’ll need', g: [['Reward', 'a number the agent gets after each step; higher is better'], ['Sparse reward', 'a reward that almost never shows up, often only at the very end'], ['Optimal policy', 'the best possible way of behaving for a task']] },
    { h: 'The problem', t: 'If the only reward comes at the very end, a beginner moving at random may **never** stumble onto it, so it never learns anything.', ex: 'A maze with one exit 200 steps away: random wandering almost never finds it.' },
    { h: 'Give hints', t: '**Reward shaping** adds small extra rewards along the way that point in the right direction, like a game of hot and cold.', a: 'shaping' },
    { h: 'A worked example', a: "p4_hotCold", t: 'Give **plus 0.1** for every step that moves closer to the exit and **minus 0.1** for every step away. Now even early wandering gets useful feedback.' },
    { h: 'The danger', a: "p4_farm", try: "Tap cells to add or remove hint coins and watch it give up on the flag.", t: 'Bad hints change what the agent is really chasing. It may **farm the hints** and ignore the real goal.', ex: 'Reward a robot for touching the ball, and it may learn to vibrate against the ball forever instead of scoring.' },
    { h: 'The safe recipe', t: 'Give each state a **potential**, a score like minus the distance to the goal. The bonus for a step is the new potential minus the old one. Loops then earn nothing overall.' },
    { h: 'Why it is safe', t: 'Ng, Harada and Russell showed in 1999 that this **potential-based** kind of shaping speeds learning without changing which policy is optimal.' },
  ],
  recap: ['Sparse rewards make learning slow', 'Shaping adds guiding hints', 'Careless hints get farmed', 'Potential-based shaping keeps the best policy'] },

{ id: 'hacking', title: 'Reward Hacking', emoji: '🐛', track: 'Rewards', pre: ['shaping'],
  hook: 'You get what you reward, not what you meant.',
  slides: [
    { h: 'Words you’ll need', g: [['Reward function', 'the rule, written by a person, that hands out points'], ['Loophole', 'a way to score points the designer never intended'], ['Reward model', 'a learned program that guesses how good an answer is']] },
    { h: 'The problem', t: 'A reward is only a **stand-in** for what we want. An agent optimises the number, not our intention, and it is very good at finding gaps.' },
    { h: 'Specification gaming', t: 'When the agent finds a **loophole** that scores high while ignoring the designer’s intent, we call it reward hacking or specification gaming.', a: 'hacking' },
    { h: 'The boat race', a: "p4_boat", t: 'In the game CoastRunners, an agent learned to **spin in circles** hitting respawning targets. It scored more than finishing the race, while catching fire.' },
    { h: 'More examples', t: 'Simulated robots exploited **physics bugs** to slide instead of walk. A Tetris-playing program learned to pause the game forever so it would never lose.' },
    { h: 'An old law', a: "p4_goodhart", ctl: [{"k": "push", "l": "optimise", "min": 0, "max": 1, "step": 0.02, "v": 0.3}], try: "Push the slider right: the score climbs while the real goal falls.", t: '**Goodhart’s law** says that when a measure becomes a target, it stops being a good measure. Reward hacking is Goodhart’s law for machines.', ex: 'Pay a team per bug fixed, and some people start writing bugs to fix.' },
    { h: 'Why it matters today', t: 'Chatbots trained with a **reward model** can learn to please the reward model, sounding confident or flattering instead of being correct.' },
    { h: 'Defences', t: 'Test in varied situations, watch what the agent actually does, keep it close to sensible behaviour, and **patch the reward** when you find a loophole.' },
  ],
  recap: ['Agents optimise the number, not the intent', 'Classic: boat circling for points', 'Goodhart’s law for machines', 'A core worry in AI safety'] },

{ id: 'curiosity', title: 'Curiosity & Intrinsic Motivation', emoji: '🔭', track: 'Rewards', pre: ['explore'],
  hook: 'Reward the agent for being surprised.',
  slides: [
    { h: 'Words you’ll need', g: [['Exploration', 'trying new things to find out what works'], ['Intrinsic reward', 'a bonus the agent gives itself, not one from the task'], ['Prediction error', 'how wrong a guess about the next moment turned out to be']] },
    { h: 'The problem', t: 'Some tasks give **almost no reward** until you have done many things right. Random button mashing will not get you there.', ex: 'In a big game, the first point might need 100 correct moves in a row.' },
    { h: 'Be curious', t: 'Children explore because new things are fun. **Intrinsic motivation** gives the agent that drive: a bonus for reaching new or surprising places.', a: 'curiosity' },
    { h: 'Counting visits', a: "p4_counts", t: 'The simplest bonus: the fewer times you have visited a place, the bigger the reward for going there. Familiar places become boring.' },
    { h: 'Measuring surprise', t: 'A second way: train a small model to predict what comes next. Where its **prediction error** is high, the place is unfamiliar, so pay a bonus there.', ex: 'Error of 0.9 in a new room earns a big bonus; 0.05 in the start room earns almost none.' },
    { h: 'A famous win', t: 'Montezuma’s Revenge is an Atari game with very rare rewards. In 2018, a curiosity method called **Random Network Distillation** beat the average human score.' },
    { h: 'The noisy TV', a: "p4_noisyTV", try: "Tap the TV to switch it off and set the agent free.", t: 'A screen of random static is **endlessly surprising**. A naive curious agent will stare at it forever and never do the task.', ex: 'Fix: only reward surprise about things the agent can actually learn to predict.' },
  ],
  recap: ['Bonus reward for novelty or surprise', 'Use visit counts or prediction error', 'Cracked very sparse games', 'Beware the noisy TV'] },

{ id: 'imitation', title: 'Imitation Learning', emoji: '🪞', track: 'Learning from people', pre: ['policy'],
  hook: 'Skip the reward: just copy an expert.',
  slides: [
    { h: 'Words you’ll need', g: [['Demonstration', 'a recording of an expert doing the task'], ['Supervised learning', 'learning from examples that come with the right answer'], ['Policy', 'the agent’s rule for picking an action in each situation']] },
    { h: 'The problem', t: 'Writing a good reward is hard, and trial and error can be slow or dangerous. But we often have **experts** who can simply show the task.', ex: 'It’s easier to drive a car than to write down a score for “good driving”.' },
    { h: 'Behaviour cloning', t: 'Record the expert, then turn each moment into an example: **this situation, the expert did that**. Train the policy to give the same answer.' },
    { h: 'The trap', t: 'The copy makes a small mistake and drifts somewhere the expert **never went**. There it has no examples, so it errs more, and the errors pile up.', a: 'imitation' },
    { h: 'A walked example', a: "p4_bcDrift", ctl: [{"k": "noise", "l": "slip size", "min": 0, "max": 1, "step": 0.05, "v": 0.5}], try: "Raise the slip size and watch small slips turn into crashes.", t: 'A car drifts 30 centimetres off the lane centre. The expert never drove there, so the learner has no idea how to recover, and drifts further.' },
    { h: 'The DAgger fix', a: "p4_dagger", t: 'Let the learner drive, then ask the expert: **what would you have done here?** Add those answers to the data and retrain. DAgger was introduced in 2011.' },
    { h: 'Where it’s used', t: 'Robots learning from people steering them remotely, self-driving prototypes, and the pre-training of chatbots, which imitate human text.', ex: 'NVIDIA’s 2016 car learned to steer from about 72 hours of human driving.' },
  ],
  recap: ['Learn by copying expert demonstrations', 'Small errors compound in unseen places', 'DAgger asks the expert about those places', 'Common in robots, cars and chatbots'] },

{ id: 'irl', title: 'Inverse RL', emoji: '🕵️', track: 'Learning from people', pre: ['imitation', 'values'],
  hook: 'Watch the expert, figure out what they want.',
  slides: [
    { h: 'Words you’ll need', g: [['Reward', 'a number the agent gets after each step; higher is better'], ['Demonstration', 'a recording of an expert doing the task'], ['Trajectory', 'the path of situations and actions in one run']] },
    { h: 'Flip the problem', t: 'Normal RL goes from **reward to behaviour**. Inverse RL goes the other way: from behaviour, work out the reward that explains it.', a: 'irl' },
    { h: 'An analogy', a: "p4_twoRoads", t: 'You watch a friend always take the longer road home. You guess they care about **avoiding traffic** more than distance. That guess is a reward.' },
    { h: 'Why not just copy?', t: 'A reward is a short, **reusable description** of the goal. In a new city with new roads, you can plan with the reward instead of copying old routes.' },
    { h: 'The ambiguity', a: "p4_ambig", t: 'Many rewards explain the same behaviour. Even “every action is worth zero” technically fits. So methods need a rule for picking a sensible answer.' },
    { h: 'Maximum entropy', t: 'A popular rule, from 2008: choose the reward that explains the expert while assuming **nothing extra**. Behaviour that fits equally well gets equal belief.', ex: 'Two routes take the same time? Assume the driver likes both equally.' },
    { h: 'Uses and cousins', t: 'Used to learn drivers’ trade-offs between speed, comfort and safety from their trajectories. **GAIL** (2016) imitates without writing the reward down at all.' },
  ],
  recap: ['Infer the reward from demonstrations', 'A reward transfers to new situations', 'Many rewards fit, so pick a sensible one', 'Max-entropy IRL and GAIL are classics'] },

{ id: 'offline', title: 'Offline RL', emoji: '💾', track: 'Learning from people', pre: ['onoff', 'funcapprox'],
  hook: 'Learn from a fixed log of data, with no new trials.',
  slides: [
    { h: 'Words you’ll need', g: [['Dataset', 'a fixed collection of past situations, actions and rewards'], ['Value', 'how much total reward the agent expects from a choice'], ['Exploration', 'trying new things to find out what works']] },
    { h: 'The setting', t: 'You get a **dataset** that someone else collected. You must learn a good policy from it, and you may **not** try anything new.', ex: 'Hospital records, past robot runs, or logs of which recommendations people clicked.' },
    { h: 'Why bother?', t: 'In many places trial and error is **unsafe or expensive**. You cannot test random treatments on patients, but you do have years of records.' },
    { h: 'Why it is hard', t: 'The learner may believe an action it has **never seen** is amazing. Normally it would try it and find out. Offline, nothing ever corrects the mistake.', a: 'offline' },
    { h: 'A walked example', a: "p4_dose", p: {"mode": "naive"}, ctl: [{"k": "dose", "l": "dose", "min": 0, "max": 6, "step": 0.1, "v": 5}], try: "Slide the dose outside the data and compare guess with reality.", t: 'The log shows doses of 1 and 2 units only. The learner’s guess for 5 units is pure invention, say a value of 100, so it picks 5. Disaster.' },
    { h: 'Stay close to the data', a: "p4_dose", p: {"mode": "cql"}, ctl: [{"k": "caution", "l": "caution", "min": 0, "max": 1, "step": 0.05, "v": 0.5}], try: "Drag caution to zero: the star runs off to an untested dose.", t: 'Offline methods are **conservative**: they lower the value of actions the data does not cover, or simply stick to actions the data contains.', ex: 'CQL pushes down values of unseen actions; IQL only learns from actions in the log.' },
    { h: 'Where it’s heading', t: 'Offline RL lets us reuse the huge logs that already exist, and often serves as a **warm start** before a small amount of careful real-world practice.' },
  ],
  recap: ['Learn only from a fixed dataset', 'Danger: overrating unseen actions', 'Conservative methods stay near the data', 'Great where trial and error is unsafe'] },

{ id: 'rlhf', title: 'RLHF', emoji: '💬', track: 'Learning from people', pre: ['ppo', 'imitation'],
  hook: 'How chatbots are tuned with human preferences.',
  slides: [
    { h: 'Words you’ll need', g: [['Language model', 'a program that writes text by predicting the next word'], ['Reward model', 'a learned program that guesses how good an answer is'], ['PPO', 'a popular, stable method for improving a policy with rewards'], ['Fine-tuning', 'extra training that adjusts an already trained model']] },
    { h: 'The problem', t: 'What score does a **helpful, honest answer** deserve? Nobody can write that rule as code. But people can easily say which of two answers is better.' },
    { h: 'Step 1: ask people', a: "p4_prefer", try: "Tap the answer you prefer and watch the scores change.", t: 'Show people two answers to the same question and ask which they **prefer**. Collect many thousands of these comparisons.', ex: 'Answer A explains clearly, answer B rambles. Most people pick A.' },
    { h: 'Step 2: a reward model', t: 'Train a **reward model** to predict which answer people would pick. Now we have an automatic judge that scores any answer.', a: 'rlhf' },
    { h: 'Step 3: practise', t: 'Use RL, often **PPO**, to fine-tune the language model so its answers get higher scores from the reward model.' },
    { h: 'Don’t drift too far', a: "p4_kl", ctl: [{"k": "beta", "l": "penalty", "min": 0.05, "max": 2, "step": 0.05, "v": 0.6}], try: "Lower the penalty and see real quality drop.", t: 'A **penalty** grows as the model moves away from its starting version. This stops it exploiting quirks of the reward model with weird text.' },
    { h: 'Famous result', t: '**InstructGPT** (2022): people preferred answers from a model tuned this way over a plain model more than 100 times bigger.' },
    { h: 'Newer variants', t: '**DPO** skips the separate RL step and learns from the comparisons directly. Other methods replace human judges with AI feedback or written principles.' },
  ],
  recap: ['People compare pairs of answers', 'A reward model learns their taste', 'RL tunes the chatbot to score well', 'A penalty stops drifting and hacking'] },

{ id: 'pomdp', title: 'Partial Observability (POMDPs)', emoji: '🌫️', track: 'Bigger worlds', pre: ['mdp'],
  hook: 'What to do when you can’t see the whole picture.',
  slides: [
    { h: 'Words you’ll need', g: [['State', 'a full description of the situation right now'], ['Observation', 'the part of the situation the agent can actually see'], ['Belief', 'the agent’s best guess, as chances, of what the true state is']] },
    { h: 'The problem', a: "p4_fog", try: "Tap a cell to send the agent exploring through the fog.", t: 'Basic RL assumes the agent sees the full **state**. Real agents only get **observations**: clues from sensors or cameras that hide part of the story.', ex: 'A robot’s camera can’t see behind a wall.' },
    { h: 'A name for it', t: 'This setting is called a **POMDP**: a partially observable Markov decision process. The world has a true state; the agent only glimpses it.' },
    { h: 'Keep a belief', t: 'The agent keeps a **belief**: chances for each possible state. Every action and new observation updates those chances.', a: 'pomdp' },
    { h: 'A walked example', a: "p4_corridor", t: 'A robot is in one of two identical corridors, 50 to 50. It spots a red door that only corridor B has. Now it believes B with about 95 percent.' },
    { h: 'Memory helps', t: 'Deep RL agents often get **memory**, through recurrent networks or transformers, so they can piece clues together over time.', ex: 'Poker: you can’t see opponents’ cards, so you remember how they have been betting.' },
    { h: 'Act to find out', t: 'Sometimes the best action earns nothing directly but **gathers information**, so later choices are better.', ex: 'Opening a door just to see what is behind it.' },
  ],
  recap: ['The agent sees observations, not the state', 'A belief is a guess with chances', 'Memory pieces clues together', 'Sometimes act just to learn more'] },

{ id: 'hrl', title: 'Hierarchical RL', emoji: '🏢', track: 'Bigger worlds', pre: ['policy', 'values'],
  hook: 'Think in sub-goals, not individual muscle twitches.',
  slides: [
    { h: 'Words you’ll need', g: [['Policy', 'the agent’s rule for picking an action in each situation'], ['Sub-goal', 'a smaller target on the way to the main goal'], ['Skill', 'a reusable routine, like “open a door”']] },
    { h: 'The problem', t: 'Long tasks need **thousands of tiny actions**. When the reward finally arrives, it is hard to tell which of those tiny steps deserve credit.' },
    { h: 'Think like a person', t: 'You don’t plan dinner one muscle twitch at a time. You think in big steps: **go to the kitchen**, cook, serve. Each big step hides many small ones.' },
    { h: 'Manager and worker', t: 'A high-level **manager** policy picks a sub-goal every so often. A low-level **worker** policy takes the small steps to reach it.', a: 'hrl' },
    { h: 'A walked example', a: "p4_manager", t: 'Manager: “reach the door”. Worker takes about 40 steps to get there. Manager then decides only 5 times for the whole task, instead of 200.' },
    { h: 'Options', a: "p4_options", t: 'An **option** is a reusable skill: a mini-policy with a rule for when it can start and when it stops. The agent picks options like ordinary actions.', ex: 'Make coffee = walk to kitchen, then grind beans, then brew.' },
    { h: 'Still open', t: 'Hand-designed sub-goals work well. Getting agents to **discover good skills on their own** is still an active research problem.' },
  ],
  recap: ['Break long tasks into sub-goals', 'Manager picks goals, worker acts', 'Options are reusable skills', 'Discovering skills is still open'] },

{ id: 'marl', title: 'Multi-Agent RL', emoji: '👥', track: 'Bigger worlds', pre: ['mdp', 'policy'],
  hook: 'When several learners share one world.',
  slides: [
    { h: 'Words you’ll need', g: [['Agent', 'a learner that makes its own choices'], ['Non-stationary', 'changing over time, so old lessons stop being true'], ['Self-play', 'training against copies of yourself']] },
    { h: 'Many agents', t: 'Many worlds hold **several learners**. They can be teammates, opponents, or a mix of both.', a: 'marl', ex: 'Teammates: robot football. Opponents: chess. A mix: city traffic or a market.' },
    { h: 'The problem', t: 'Everyone else is learning too, so the world you face keeps changing. A trick that worked yesterday stops working once others adapt. It is **non-stationary**.' },
    { h: 'A walked example', a: "p4_penalty", t: 'You learn the goalkeeper always dives left, so you shoot right. The keeper learns too and starts diving right. Your old lesson is now wrong.' },
    { h: 'Train together, act alone', a: "p4_ctde", t: 'A popular recipe: during training, let a coach see **everyone’s information**. At test time, each agent acts only on what it can see itself.' },
    { h: 'Self-play', t: 'In competitive games, an agent can train against **copies of itself**. As it improves, so does its opponent, giving a steady stream of good practice.' },
    { h: 'Highlights', t: '**OpenAI Five** beat the Dota 2 world champions in 2019. **AlphaStar** reached Grandmaster level in StarCraft II. In hide-and-seek, agents invented tool use.' },
  ],
  recap: ['Several agents learning in one world', 'Others adapting makes the world change', 'Train together, act alone', 'Self-play gives endless opponents'] },

{ id: 'sim2real', title: 'Sim-to-Real & Domain Randomisation', emoji: '🦾', track: 'Bigger worlds', pre: ['loop'],
  hook: 'Train in simulation, then deploy on a real robot.',
  slides: [
    { h: 'Words you’ll need', g: [['Simulator', 'a computer program that imitates the physical world'], ['Reality gap', 'the differences between the simulator and the real world'], ['Policy', 'the robot’s rule for choosing what to do']] },
    { h: 'Why simulate?', t: 'Real robots are **slow**, they break, and you can’t run a thousand of them at once. A simulator runs thousands of copies, faster than real time, for free.' },
    { h: 'The reality gap', a: "p4_gap", ctl: [{"k": "mu", "l": "real friction", "min": 0.1, "max": 0.6, "step": 0.01, "v": 0.45}], try: "Set the real friction to 0.30 to match the simulator.", t: 'Simulated friction, weight and lighting never match reality exactly. A policy that is perfect in the simulator can **stumble** on the real robot.', ex: 'A robot that learned on a perfectly smooth simulated floor slips on a real rug.' },
    { h: 'Randomise everything', t: '**Domain randomisation**: during training, keep changing friction, masses, colours, lighting and delays at random.', a: 'domainRand' },
    { h: 'Why that works', a: "p4_dr", ctl: [{"k": "range", "l": "randomise ±", "min": 0, "max": 0.25, "step": 0.01, "v": 0.02}], try: "Widen the randomisation until every real-world test passes.", t: 'After seeing thousands of slightly different worlds, the policy must handle all of them. The real world then looks like **just one more variation**.', ex: 'Train with friction anywhere from 0.5 to 1.5, and the real 0.9 is easy.' },
    { h: 'A famous example', t: 'In 2019, OpenAI’s robot hand solved a **Rubik’s cube** after training only in heavily randomised simulation.' },
    { h: 'Walking robots', t: 'Four-legged robots, such as ANYmal, learned to walk over rough ground in simulation and then did it outdoors, on real hills and snow.' },
  ],
  recap: ['Simulation is cheap and runs in parallel', 'The reality gap breaks naive transfer', 'Randomise the simulator during training', 'Reality becomes one more variation'] },
// ───────────── v10 additions ─────────────
// new topics, part 1
{ id: 'rainbow', title: 'Rainbow: Dueling & Distributional DQN', emoji: '🌈', track: 'Deep RL', pre: ['doubledqn', 'replay'],
  hook: 'Six fixes for DQN, stacked into one strong agent.',
  slides: [
    { h: 'Words you’ll need', g: [['Q-value', 'how much total reward you expect after taking an action in a situation.'], ['DQN', 'a neural network that learns Q-values for every action, used for Atari games.'], ['Return', 'the total reward collected from now until the end.'], ['Distribution', 'how likely each possible outcome is, not just the average.']] },
    { h: 'Many fixes, one agent', a: 'n1_rainbowBars', t: 'After DQN, researchers found several separate fixes, each helping a little. In 2018 a DeepMind team asked a simple question: what if we **use them all at once**? The result was called **Rainbow**.' },
    { h: 'Dueling: two heads', a: 'n1_dueling', ctl: [{ k: 'v', l: 'V state value', min: 0, max: 6, step: 0.1, v: 3 }], try: 'Drag V: every Q bar moves together, the best action stays gold.', t: 'A dueling network splits its output in two. One head guesses **V**, how good the situation is. The other guesses **A**, how much better each action is. Q is simply V plus A.' },
    { h: 'Why dueling helps', t: 'In many moments the action barely matters. The network can still learn **how good the situation is** from every step, without learning each action separately.', ex: 'Driving on an empty road: gas, left or right all lead to about the same future.' },
    { h: 'Distributional: keep the whole spread', a: 'n1_distrib', t: 'Normal DQN predicts one number per action: the average return. A **distributional** agent predicts the chances of many possible returns. The C51 version uses 51 bins.' },
    { h: 'Why a spread helps', t: 'Two actions can share an average but carry very different risk. Learning the **full shape** gives the network a richer signal to learn from, and in practice it scored better.', ex: 'A safe route always gives about 5. A risky one gives 0 or 10. Both average 5.' },
    { h: 'The other ingredients', a: 'p2_buffer', p: { mode: 'prio' }, ctl: [{ k: 'pr', l: 'priority', min: 0, max: 1, step: 0.1, v: 0.6 }], try: 'Drag priority to 0: every memory is replayed equally often.', cap: 'Ten stored memories. Red bars show how surprising each was, teal bars how often it was replayed. Higher priority replays surprising ones more.', t: '**Prioritised replay** replays surprising memories more often. **Multi-step returns** use a few real rewards before trusting a guess. Add double Q-learning and noisy networks for exploration.' },
    { h: 'Together is better', t: 'On 57 Atari games, the combination beat every single fix on its own. Removing parts showed that **prioritised replay** and **multi-step returns** mattered most.', ex: 'A lesson that stuck: small, compatible improvements often add up.' },
  ],
  recap: ['Rainbow = DQN plus six known fixes', 'Dueling: Q = V (situation) + A (action)', 'Distributional: learn the spread of returns', 'Prioritised replay and multi-step helped most'] },

{ id: 'a2c', title: 'A2C & A3C', emoji: '👯', track: 'Policy Gradients', pre: ['actorcritic'],
  hook: 'Many players learning at once beats one player alone.',
  slides: [
    { h: 'Words you’ll need', g: [['Actor', 'the part that chooses actions: the policy.'], ['Critic', 'the part that guesses how good a situation is.'], ['Worker', 'one copy of the agent playing its own copy of the game.'], ['Update', 'one small change to the network’s numbers to do better.']] },
    { h: 'One player is slow', t: 'A single actor-critic learns from moments that come **one after another**, and they look almost the same. It also gathers data slowly. A replay memory can’t fix this, because actor-critic needs fresh data from its current policy.' },
    { h: 'Many players at once', a: 'n1_parallel', ctl: [{ k: 'k', l: 'workers', min: 1, max: 8, step: 1, v: 4 }], try: 'Drag workers down to 1: the batch turns one colour.', t: 'The fix: run **many copies** of the game side by side, each with its own worker. Together they gather data faster, and their moments are naturally **varied**.' },
    { h: 'A3C: send when ready', a: 'n1_asyncSync', t: 'In **A3C** (2016), each worker computes its own update and sends it to the shared network **the moment it’s done**, without waiting. It ran well on ordinary CPUs.', ex: 'The catch: a worker may still be acting with a slightly out-of-date copy of the network.' },
    { h: 'A2C: wait, then update together', t: '**A2C** is the synchronous version. All workers play a few steps, then their experience is pooled into **one batch** and one update is made. Simpler, and it suits GPUs well.', ex: 'OpenAI reported that A2C matched A3C in their tests, while being easier to run.' },
    { h: 'The “advantage” in the name', a: 'actorCritic', t: 'Both use the critic to compute the **advantage**: how much better an action turned out than expected. Better than expected: do it more often. Worse: do it less.' },
    { h: 'Where it went', t: 'Running **many environments in parallel** became standard practice. PPO, today’s workhorse, is usually trained exactly this way.', ex: 'Typical setups run 8 to thousands of game copies at once.' },
  ],
  recap: ['Many parallel workers: more and more varied data', 'A3C: each worker updates on its own', 'A2C: wait for all, one combined update', 'Parallel environments are now standard'] },

{ id: 'trpo', title: 'TRPO: Trust Regions', emoji: '🪢', track: 'Policy Gradients', pre: ['actorcritic'],
  hook: 'Improve the policy, but never jump too far at once.',
  slides: [
    { h: 'Words you’ll need', g: [['Policy', 'the agent’s rule for choosing actions, usually as probabilities.'], ['Gradient', 'the direction to nudge the network’s numbers to do better.'], ['KL divergence', 'a score of how different two sets of probabilities are. Zero means identical.'], ['Trust region', 'the zone around the current policy where our estimates can be believed.']] },
    { h: 'Big steps can be fatal', a: 'n1_trustRegion', ctl: [{ k: 'd', l: 'trust region', min: 0.2, max: 3, step: 0.1, v: 0.8 }], try: 'Widen the trust region past 2.2 and watch a step leap off the cliff.', t: 'A gradient tells you which way is uphill, but only **right where you stand**. A big step can land on a cliff. Worse, a ruined policy then collects ruined data.' },
    { h: 'Trust the map only nearby', t: '**TRPO**, from John Schulman and colleagues in 2015, builds a local estimate of how much better a change would be. It only trusts that estimate **inside a small region** around the current policy.' },
    { h: 'Measure distance by behaviour', a: 'n1_klMeter', ctl: [{ k: 'kl', l: 'KL limit', min: 0.01, max: 0.3, step: 0.01, v: 0.05 }], try: 'Lower the KL limit: each update becomes a smaller nudge.', t: 'The region is measured by how much the **action probabilities** change, using KL divergence. Not by how much the weights change: a tiny weight change can flip behaviour.' },
    { h: 'How a step is found', t: 'Pick the direction that improves the estimate most while the average KL stays **below a limit**, like 0.01. Then check the real result. If it got worse or broke the limit, **halve the step** and check again.', ex: 'Like testing the ice before putting your full weight on it.' },
    { h: 'Steady progress', t: 'The payoff is **steady, reliable improvement** instead of sudden collapses. TRPO trained simulated robots to walk, hop and swim, straight from raw joint readings.' },
    { h: 'Why PPO took over', a: 'ppoClip', t: 'TRPO needs heavy second-order maths that is slow and awkward with big networks. **PPO** (2017) gets a similar “don’t move too far” effect with a simple **clipped** objective, so it largely replaced TRPO.' },
  ],
  recap: ['Big policy steps can wreck performance', 'TRPO: only move within a trust region', 'Distance = change in behaviour (KL)', 'PPO later made the idea simple'] },
// new topics, part 2
{ id: 'muzero', title: 'MuZero', emoji: '🧠', track: 'Model-based', pre: ['alphazero', 'worldmodels'],
  hook: 'Plan like AlphaZero, without being told the rules.',
  slides: [
    { h: 'Words you’ll need', g: [['Model', 'the agent’s own simulator: it predicts what happens after a move'], ['Hidden state', 'a compact summary the network invents for itself, not a picture'], ['Planning', 'trying out moves in your head before making a real one'], ['Tree search', 'exploring a branching tree of possible moves to find a good one']] },
    { h: 'The puzzle', t: 'AlphaZero planned by simulating the game with its **real rules**. But Atari games, robots and most real problems come with **no rulebook** to simulate. How do you plan without one?' },
    { h: 'Learn your own rules', a: 'n2_mzPipeline', t: 'MuZero, from DeepMind in 2019, learns three small functions. **h** turns the screen into a hidden state. **g** predicts the next hidden state and reward for a move. **f** guesses good moves and a value.' },
    { h: 'Only what matters', a: 'n2_pixelsVsValue', t: 'Some world models try to redraw every pixel of the next screen. MuZero’s model only has to get **rewards, values and good moves** right. Everything else can be ignored.', ex: 'A chess player imagines who is winning, not the wood grain of the board.' },
    { h: 'Imagine, then act', a: 'n2_mzImagine', try: 'Tap ⬅ or ➡ to imagine a move and see what MuZero predicts.', t: 'From the current hidden state, MuZero imagines sequences of moves **entirely inside the network**. Each imagined path is scored by its predicted rewards plus the value where it ends.' },
    { h: 'Tree search in its head', a: 'mcts', cap: 'The same tree search as AlphaZero, but every branch here is imagined by MuZero’s learned model. Gold follows promising moves, green carries results back up.', t: 'It runs the same **tree search** as AlphaZero, about 50 imagined moves per real move in Atari. Then it plays the move the search visited most.' },
    { h: 'How it learns', t: 'After real play, the model is trained so its imagined rewards and values **match what really happened** a few steps later, and its move guesses match what the search chose.' },
    { h: 'Results', t: 'MuZero matched AlphaZero at **chess, shogi and Go** without being told the rules, and set new records on many **Atari** games. A version was later used to tune video compression for YouTube.' },
  ],
  recap: ['Plans without knowing the rules', 'Learns a hidden-state model: h, g and f', 'Predicts rewards, values, moves: not pixels', 'Tree search entirely in imagination'] },

{ id: 'successor', title: 'Successor Features', emoji: '🔮', track: 'Model-free', pre: ['td'],
  hook: 'Know where you’ll go, and new goals cost almost nothing.',
  slides: [
    { h: 'Words you’ll need', g: [['Value', 'how much total future reward you expect from a place'], ['Discount', 'counting sooner things more than later ones, using a number like 0.8'], ['Feature', 'a measurable property of a place, like “has food” or “is wet”'], ['Reward weight', 'how much you care about each feature right now']] },
    { h: 'The problem', t: 'A normal value function bakes in **one reward**. If the food moves somewhere else, a TD learner has to **relearn** its values, step by step, over many episodes.' },
    { h: 'Split the question', t: 'Ask two separate things. **Where will I end up?** That depends only on how you move around. **What do I like there?** That is the reward, and it may change.', ex: 'Knowing your city’s streets helps whether today you want coffee or the gym.' },
    { h: 'Where will I end up?', a: 'n2_srOccupancy', t: 'The **successor representation** stores, for each place, how often you’ll visit every other place in the future, with far-off visits counted less. Peter Dayan proposed it in 1993, and it is learned with TD.' },
    { h: 'Values for free', a: 'n2_srSwap', ctl: [{ k: 'apple', l: '🍎', min: -1, max: 1, step: .1, v: 1 }, { k: 'water', l: '💧', min: -1, max: 1, step: .1, v: 0 }], try: 'Drag 🍎 and 💧: the values update instantly.', t: 'Value is just **future visits × reward at each place**. Change the reward and multiply again: new values appear **instantly**, with no new experience.' },
    { h: 'Features, not places', t: 'Big worlds have too many places to count each one. **Successor features** instead predict how much of each **feature** you’ll see in the future, like food or water. Value is those predictions times the reward weights.' },
    { h: 'The race', a: 'n2_srVsRelearn', t: 'When the goal moves, the successor agent just re-multiplies and adapts at once. Plain TD has to wait for the change to **spread back** through its values.' },
    { h: 'Catch and uses', t: 'The visit counts assume your **old way of moving**. If the best route changes a lot, they must be updated too. Neuroscientists also use the idea to describe the brain’s **predictive maps**.' },
  ],
  recap: ['Split “where will I go” from “what do I like”', 'Successor counts are learned with TD', 'New reward → new values in one multiply', 'Assumes your behaviour stays similar'] },

{ id: 'contextual', title: 'Contextual Bandits', emoji: '📰', track: 'Bandits', pre: ['ucb'],
  hook: 'Same slot machines, but now you know who’s playing.',
  slides: [
    { h: 'Words you’ll need', g: [['Context', 'information you see before choosing, like who the visitor is'], ['Arm', 'one of the options you can pick, like one article to show'], ['Click rate', 'the share of times people click when they are shown it'], ['Exploration bonus', 'extra score for options you haven’t tried enough yet']] },
    { h: 'One size doesn’t fit all', t: 'A plain bandit hunts for the **single best arm**. But the best article for a student is not the best for a retiree. Picking one winner for everyone leaves clicks on the table.' },
    { h: 'Look before you choose', a: 'n2_ctxNews', t: 'A **contextual bandit** sees a context first, then picks an arm, then gets a reward. It learns which arm is best **for each kind of situation**.' },
    { h: 'A row per context', a: 'n2_ctxTable', ctl: [{ k: 'bonus', l: 'bonus', min: 0, max: 2, step: .1, v: .6 }], try: 'Drag the bonus: at 0 it can get stuck, high values keep testing.', t: 'With only a few kinds of visitors, keep separate guesses for each one and run **UCB in every row**. Each row explores and settles on its own.' },
    { h: 'Too many contexts', a: 'n2_ctxLine', t: 'Real visitors have hundreds of details, so one row each is impossible. **LinUCB** scores each article as **features × learned weights**, plus a bonus that is bigger for unfamiliar kinds of visitors.' },
    { h: 'Where it’s used', t: 'Yahoo! used LinUCB on its **news front page** in 2010. Contextual bandits now pick ads, recommendations, notification times and even which treatment to offer a patient.' },
    { h: 'Still not full RL', t: 'Your choice does not change **who arrives next**. When actions shape future situations, like moves in a game, you need full RL with states and returns.' },
    { h: 'A common pitfall', t: 'You only see clicks for articles you **actually showed**. Judging a new strategy from old logs needs care, for example re-weighting the logged choices.', ex: 'If you never showed 🌻 garden news to students, the logs can’t tell you if they’d like it.' },
  ],
  recap: ['See the context, then pick an arm', 'Best arm can differ per situation', 'LinUCB: features × weights + bonus', 'Actions don’t change the next context'] },
// new part 3
{ id: 'dt', title: 'Decision Transformer', emoji: '🔤', track: 'Learning from people', pre: ['offline'],
  hook: 'What if RL were just predicting the next word?',
  slides: [
    { h: 'Words you’ll need', g: [['Transformer', 'the kind of neural network behind chatbots: it reads a sequence, predicts what comes next.'], ['Trajectory', 'the full record of one game: what it saw, what it did, what it earned, in order.'], ['Return-to-go', 'how much reward is still to be collected from this moment until the end.'], ['Token', 'one item in the sequence, like one word in a sentence.']] },
    { h: 'A different question', t: 'Classic RL asks: which action has the **highest value**? A Decision Transformer asks something simpler: what would a player do next if they were on track to finish with a score of X?' },
    { h: 'A game written as a sentence', t: 'Each step of a logged game becomes three tokens: the **return-to-go**, the state, and the action. A transformer reads the sentence so far and predicts the next action, like predicting the next word.', a: 'n3_tokens' },
    { h: 'Counting down the score', t: 'The return-to-go starts at the final score and drops every time a reward arrives. It tells the model how much is still wanted from here.', ex: 'Rewards 0, 0, 5, 0, 10. Return-to-go: 15, 15, 15, 10, 10. After the last reward it is 0.' },
    { h: 'Ask for a score', t: 'At play time you type in the score you want as the first token. Ask for a **high** score and it imitates the best behaviour in the data. Ask for a low one and it plays badly on purpose.', a: 'n3_askScore', ctl: [{ k: 'target', l: 'score asked', min: 0, max: 12, step: 1, v: 8 }], try: 'Slide the asked-for score and watch which logged run the agent copies.' },
    { h: 'Training is plain prediction', t: 'There are no value estimates and no Bellman updates. The model only learns to predict the logged action, using the same **supervised learning** tools as language models. That makes training simple and stable.' },
    { h: 'Where it came from', t: 'Introduced by Chen and colleagues in 2021, alongside the similar Trajectory Transformer. On standard offline benchmarks like Atari games and robot locomotion, it held its own against offline RL methods.' },
    { h: 'The catch: no stitching', t: 'It copies whole runs, so it struggles to **combine pieces** of different runs into a better one. And asking for a score far above anything in the data does not work: it can only imitate what it has seen.', a: 'n3_stitch' },
  ],
  recap: ['Write each game as tokens: return-to-go, state, action', 'Predict the next action, like the next word', 'Ask for a score at play time', 'Weak at stitching pieces of runs together'] },

{ id: 'grpo', title: 'RL for LLM Reasoning (GRPO)', emoji: '🧮', track: 'Learning from people', pre: ['rlhf'],
  hook: 'Let the model try, let a checker grade it, repeat.',
  slides: [
    { h: 'Words you’ll need', g: [['LLM', 'large language model: an AI that writes text one word at a time.'], ['Verifiable reward', 'a score a program can check, like “is the final answer correct?”'], ['Critic', 'a second network that guesses how well things will go from here.'], ['Advantage', 'how much better one try was than what was expected.']] },
    { h: 'No human judge needed', t: 'In RLHF, people compare answers. But for maths or code, a **program can check** the answer: does the number match, do the tests pass? That gives a cheap, honest reward.' },
    { h: 'Many tries per question', t: 'For each question, the model writes a **group** of answers, say 8. A checker gives each one 1 if right and 0 if wrong.', a: 'n3_group', try: 'Tap to sample a fresh group of 8 answers.' },
    { h: 'Compare within the group', t: 'Each answer’s advantage is its score minus the **group average**. Answers better than their siblings get pushed up, worse ones pushed down. This is the core of GRPO, Group Relative Policy Optimisation.', ex: '8 tries, 3 right: average 0.375. Right answers get plus 0.625, wrong ones minus 0.375.' },
    { h: 'No critic required', t: 'PPO usually trains a separate critic to estimate the expected score. GRPO uses the group average as that estimate instead, which saves a whole network and a lot of memory.' },
    { h: 'Stay close to the start', t: 'Like RLHF, a **penalty** keeps the model near its original version, and updates are clipped like in PPO. Without it, the model could drift into strange text that happens to fool the checker.' },
    { h: 'Where it’s used', t: 'GRPO was introduced in the DeepSeekMath paper in 2024 and used to train **DeepSeek-R1** in 2025. During that training, answers grew longer and more often included checking their own work.', a: 'n3_lengthGrow' },
    { h: 'When nothing is learned', t: 'If all 8 tries are right, or all wrong, every advantage is zero: **no signal**. Questions must be neither too easy nor too hard. And checkers can be gamed, just like any reward.', a: 'n3_zeroSignal', ctl: [{ k: 'p', l: 'chance right', min: .05, max: .95, step: .05, v: .5 }, { k: 'n', l: 'group size', min: 2, max: 16, step: 1, v: 8 }], try: 'Make questions very easy or very hard and watch useful groups vanish.' },
  ],
  recap: ['A program checks answers: a cheap, honest reward', 'Sample a group, score each try', 'Advantage = score minus group average, no critic', 'All-right or all-wrong groups teach nothing'] },

{ id: 'saferl', title: 'Safe & Constrained RL', emoji: '🦺', track: 'Rewards', pre: ['hacking'],
  hook: 'Win the game, but never cross the line.',
  slides: [
    { h: 'Words you’ll need', g: [['Constraint', 'a limit that must hold, like “fewer than 1 bump per 100 trips”.'], ['Cost', 'a second number, besides reward, that counts bad events.'], ['Penalty weight', 'how much reward each unit of cost takes away.'], ['Shield', 'a safety filter that blocks a dangerous action before it happens.']] },
    { h: 'Why reward alone struggles', t: 'You could just subtract a penalty for every crash. But then you must pick the **weight** by hand. Too small and the agent speeds and crashes. Too big and it barely moves.', a: 'n3_tradeoff', ctl: [{ k: 'w', l: 'penalty weight', min: 0, max: 10, step: .5, v: 2 }], try: 'Slide the penalty weight from 0 to 10 and watch speed versus bumps.' },
    { h: 'Two numbers, not one', t: 'Constrained RL keeps **reward and cost separate**. The goal: get as much reward as possible while the average cost stays under a budget you choose.', ex: 'Delivery robot: reward for fast deliveries, cost for each bump, budget at most 1 bump per 100 trips.' },
    { h: 'A penalty that tunes itself', t: 'Instead of fixing the weight, let it **adapt**. If cost is over budget, raise the weight. If cost is under, lower it. Like a thermostat. This is called the Lagrangian method.', a: 'n3_lagrange', ctl: [{ k: 'budget', l: 'budget', min: .5, max: 5, step: .5, v: 2 }], try: 'Change the budget and watch the weight rise or fall until cost fits.' },
    { h: 'A worked step', t: 'Budget: 1 bump per 100 trips. This round the agent bumped 3 times, so the weight goes up a little, say from 0.5 to 0.7. Next round bumps drop to 0.4, so the weight eases back down.' },
    { h: 'Shields', t: 'A shield checks every action before it runs. If a known safety rule says the move leads to danger, it **swaps in a safe move**. The agent still learns, but never takes that step.', a: 'n3_shield', try: 'Tap to switch the shield on and off and compare the falls.' },
    { h: 'Where it’s used', t: 'Robots that must not fall, self-driving tests, and systems with hard limits like energy or temperature. OpenAI’s Safety Gym in 2019 made a common test bed, and methods like Constrained Policy Optimisation and PPO-Lagrangian are popular.' },
    { h: 'Limits to know', t: 'Constraints usually hold **on average**, not on every single run, and may be broken while still learning. A shield is only as good as its safety rule. And a cost signal can be gamed, just like reward.' },
  ],
  recap: ['Keep reward and cost as separate signals', 'Max reward subject to a cost budget', 'Lagrangian: the penalty weight adapts itself', 'Shields block known dangerous actions'] },
// new topics, part 4
{ id: 'her', title: 'Goal-Conditioned RL & HER', emoji: '🎯', track: 'Deep RL', pre: ['replay'],
  hook: 'Missed the target? Pretend you were aiming there all along.',
  slides: [
    { h: 'Words you’ll need', g: [['Goal', 'the thing the agent is asked to reach, like a spot on a table.'], ['Replay buffer', 'a memory of past moves the agent keeps studying.'], ['Sparse reward', 'a reward that is zero almost always, and only pays at success.']] },
    { h: 'One agent, many goals', a: 'n4_goalInput', try: 'Tap anywhere in the box to put a new goal there.', t: 'Normally an agent learns one task. A **goal-conditioned** agent gets the goal as part of its input, so the same policy can reach any target you name.', ex: 'A robot arm told “put the block at the left corner” or “at the centre”, with no retraining.' },
    { h: 'The sparse reward problem', t: 'Say the arm only gets plus 1 when the block lands exactly on target. At first it almost never succeeds, so almost every reward is 0, and there is nothing to learn from.' },
    { h: 'The hindsight trick', a: 'n4_herRelabel', t: 'After a miss, **Hindsight Experience Replay** asks: where did I actually end up? It stores the same attempt again, as if that spot had been the goal. Now it is a success.' },
    { h: 'Why that is not cheating', t: 'The moves really do reach the spot where the block landed. So the agent truly learns how to reach that spot. Over time it learns to reach everywhere, including the real target.' },
    { h: 'How it fits together', a: 'replay', cap: 'Each square is one stored memory. With HER, every attempt is stored twice: once with the real goal and reward 0, and once relabelled with the reached spot and reward plus 1.', t: 'Each attempt goes into the **replay buffer** twice: once with the real goal, once relabelled. Training samples from both, so useful rewards show up from day one.' },
    { h: 'Where it is used', t: 'HER was introduced in 2017 by OpenAI researchers for robot arms pushing, sliding and picking up objects. It works with off-policy learners like DDPG, which can learn from stored memories.' },
    { h: 'Limits', t: 'Relabelling only helps when any reached state can serve as a goal. It struggles when goals are abstract, like “win the game”, where an accidental outcome is not a useful target.' },
  ],
  recap: ['Goal-conditioned: the goal is part of the input', 'Sparse rewards leave nothing to learn from', 'HER relabels misses as successes for the reached spot', 'Works with off-policy replay'] },

{ id: 'rnd', title: 'RND & Go-Explore', emoji: '🗝️', track: 'Rewards', pre: ['curiosity'],
  hook: 'How agents finally cracked the hardest exploration game.',
  slides: [
    { h: 'Words you’ll need', g: [['Exploration bonus', 'extra reward the agent gives itself for reaching new places.'], ['Neural network', 'a function with many adjustable numbers, trained to make predictions.'], ['Archive', 'a saved list of interesting places reached so far, and how to get back.']] },
    { h: 'The hard case', t: 'In the Atari game **Montezuma’s Revenge**, you need long chains of exact moves before any points appear. Random exploration almost never gets there, so early agents scored close to 0.' },
    { h: 'Random Network Distillation', t: 'Take one network with fixed random numbers. Train a second network to copy its output. On familiar screens the copy is good; on **new** screens it is bad. That copying error is the bonus.', ex: 'Like a tourist: a street you have walked ten times is boring, a new one is exciting.' },
    { h: 'Novelty fades with visits', a: 'n4_rndNovelty', ctl: [{ k: 'beta', l: 'bonus weight', min: 0, max: 3, step: 0.1, v: 1.5 }], try: 'Set the bonus weight to 0 and watch the robot stay in the first room.', t: 'Every visit makes a place more familiar, so its bonus shrinks. The agent is pulled towards the places it has seen least, room after room.' },
    { h: 'The noisy TV trap', a: 'p4_noisyTV', cap: 'A TV showing random static is always unpredictable, so a naive curiosity bonus never runs out there. RND resists this better, because its random target network gives the same output for the same screen.', try: 'Tap the TV to switch it off.', t: 'Prediction-based curiosity can get hooked on pure randomness, like TV static. RND is less fooled, since its target does not change.' },
    { h: 'Go-Explore', a: 'n4_goExplore', t: 'A different idea from 2019: keep an **archive** of places reached. Each round, pick a promising one, return there by replaying the saved route, then explore from it. Never forget a good spot.' },
    { h: 'The results', t: 'RND, from OpenAI in 2018, was the first to beat average human play on Montezuma’s Revenge without demonstrations. Go-Explore, from Uber AI, later scored far higher, into the millions with some extra hints about the game.' },
    { h: 'The lesson', t: 'Two ingredients matter: reward yourself for **novelty**, and **remember** how to get back to the frontier, instead of hoping to stumble there again.' },
  ],
  recap: ['Sparse games need smart exploration', 'RND: bonus = error copying a random network', 'Go-Explore: remember, return, then explore', 'Both cracked Montezuma’s Revenge'] },

{ id: 'curriculum', title: 'Curriculum Learning', emoji: '📚', track: 'Bigger worlds', pre: ['shaping'],
  hook: 'Nobody learns calculus before counting. Neither should agents.',
  slides: [
    { h: 'Words you’ll need', g: [['Task', 'one version of the problem, like one level of a game.'], ['Curriculum', 'an ordered list of tasks, from easy to hard.'], ['Success rate', 'how often the agent solves a task, from 0 to 100 percent.']] },
    { h: 'Why start easy?', t: 'An agent learns only from rewards. On a task far too hard, it never succeeds, so it never sees a reward, and it learns nothing at all.' },
    { h: 'Easy steps up', a: 'n4_curriculum', ctl: [{ k: 'start', l: 'start level', min: 1, max: 6, step: 1, v: 1 }], try: 'Start at level 4 or higher and watch the robot get stuck.', t: 'Give it the easy levels first. Small wins teach skills that make the next level reachable. This is a **curriculum**, just like school.' },
    { h: 'A real example', t: 'To teach a robot hand to stack blocks, first ask for one block lifted a little. Then lifted high, then placed, then stacked. Each step reuses what came before.' },
    { h: 'Automatic curricula', a: 'n4_autoCurric', t: 'Hand-making a curriculum is hard. Instead, a **teacher** program can pick tasks where the agent succeeds about half the time: not boring, not hopeless.' },
    { h: 'Self-play is a curriculum too', a: 'selfplay', cap: 'Two copies of the agent play each other. As one improves, its opponent gets tougher, so the difficulty rises on its own.', t: 'When an agent plays against copies of itself, the opponent improves exactly as fast as it does. The difficulty is always about right.' },
    { h: 'Pitfalls', t: 'Too slow a curriculum wastes time on easy tasks. Too fast, and the agent falls behind. Skills learned on easy tasks can also be forgotten if they never come up again.' },
  ],
  recap: ['Too hard means no rewards, means no learning', 'Order tasks from easy to hard', 'Teachers can pick tasks near 50% success', 'Self-play makes its own curriculum'] },

{ id: 'metarl', title: 'Meta-RL: Learning to Learn', emoji: '🧬', track: 'Bigger worlds', pre: ['pomdp'],
  hook: 'Train on many tasks so a new one takes minutes, not months.',
  slides: [
    { h: 'Words you’ll need', g: [['Task', 'one problem, like one maze or one slot machine setup.'], ['Adapt', 'get good at a new task using only a little experience.'], ['Memory', 'information the agent carries forward from earlier steps.']] },
    { h: 'The idea', t: 'Ordinary RL learns one task slowly. **Meta-RL** trains on many related tasks, so the agent learns how to learn. Faced with a new task, it adapts after only a few tries.', ex: 'After many video games, you figure out a new one in minutes.' },
    { h: 'A quick learner', a: 'n4_metaAdapt', try: 'Tap the box to hide the prize behind a new door.', t: 'Every task hides a prize behind one of three doors. A meta-learned agent has learned a strategy: check each door once, then stick with the winner.' },
    { h: 'Learning lives in memory', a: 'pomdp', cap: 'The agent can’t see which task it is in, a bit like this foggy maze. It has to work it out from what happens, and keep that guess in its memory.', t: 'One family, called **RL squared**, uses a network with memory. It is never told which task it is in, so it must work it out from rewards, inside its memory.' },
    { h: 'A good starting point', a: 'n4_mamlInit', t: 'Another family, called **MAML**, learns starting numbers for the network. From there, a few ordinary learning steps are enough to fit any task in the family.' },
    { h: 'Where it matters', t: 'Robots that must handle a new object or a slippery floor, recommendation systems facing a new user, and agents that must quickly read an unfamiliar opponent.' },
    { h: 'The catch', t: 'Meta-RL only helps on tasks similar to the training family. Training is expensive, since every update needs whole learning runs on many tasks.' },
  ],
  recap: ['Train on many tasks to learn how to learn', 'Adapt to a new task in a few tries', 'RL squared: adaptation happens in memory', 'MAML: a start point that fits fast'] },
];
